INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('fe-Push_Press', 'Push Press', 'shoulders', 'shoulders', '["quadriceps","triceps"]', 'barbell', 'olympic weightlifting', 'expert', '[]', NULL, '["Push_Press/0.jpg","Push_Press/1.jpg"]', 6, 'sets', 0, 'fedb', 1),
('fe-Push_Press_-_Behind_the_Neck', 'Push Press - Behind the Neck', 'shoulders', 'shoulders', '["calves","quadriceps","triceps"]', 'barbell', 'olympic weightlifting', 'intermediate', '["Standing with the weight racked on the back of the shoulders, begin with the dip. With your feet directly under your hips, flex the knees without moving the hips backward. Go down only slightly, and reverse direction as powerfully as possible. Drive through the heels create as much speed and force as possible, moving the bar in a vertical path.","Using the momentum generated, finish pressing the weight overhead be extending through the arms.","Return to the starting position, using your legs to absorb the impact."]', NULL, '["Push_Press_-_Behind_the_Neck/0.jpg","Push_Press_-_Behind_the_Neck/1.jpg"]', 6, 'sets', 0, 'fedb', 1),
('fe-Pushups', 'Pushups', 'chest', 'chest', '["shoulders","triceps"]', 'body only', 'strength', 'beginner', '["Lie on the floor face down and place your hands about 36 inches apart while holding your torso up at arms length.","Next, lower yourself downward until your chest almost touches the floor as you inhale.","Now breathe out and press your upper body back up to the starting position while squeezing your chest.","After a brief pause at the top contracted position, you can begin to lower yourself downward again for as many repetitions as needed."]', NULL, '["Pushups/0.jpg","Pushups/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Pushups_Close_and_Wide_Hand_Positions', 'Pushups (Close and Wide Hand Positions)', 'chest', 'chest', '["shoulders","triceps"]', 'body only', 'strength', 'beginner', '["Lie on the floor face down and body straight with your toes on the floor and the hands wider than shoulder width for a wide hand position and closer than shoulder width for a close hand position. Make sure you are holding your torso up at arms length.","Lower yourself until your chest almost touches the floor as you inhale.","Using your pectoral muscles, press your upper body back up to the starting position and squeeze your chest. Breathe out as you perform this step.","After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions."]', NULL, '["Pushups_Close_and_Wide_Hand_Positions/0.jpg","Pushups_Close_and_Wide_Hand_Positions/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Pyramid', 'Pyramid', 'back', 'lower back', '["shoulders"]', 'exercise ball', 'stretching', 'beginner', '["Start off by rolling your torso forward onto the ball so your hips rest on top of the ball and become the highest point of your body.","Rest your hands and feet on the floor. Your arms and legs can be slightly bent or straight, depending on the size of the ball, your flexibility, and the length of your limbs. This also helps develop stabilizing strength in your torso and shoulders."]', NULL, '["Pyramid/0.jpg","Pyramid/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Quad_Stretch', 'Quad Stretch', 'upper legs', 'quadriceps', '[]', 'other', 'stretching', 'intermediate', '["Lay on your side. Loop a belt, rope, or band around your top foot. Flex the knee and extend your hip, attempting to touch your glutes with your foot, and holding the belt with your hands. This will be your starting position.","With the belt being held over the shoulder or overhead, gently pull to increase the stretch in the quadriceps. Hold for 10-20 seconds, and then switch sides."]', NULL, '["Quad_Stretch/0.jpg","Quad_Stretch/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Quadriceps-SMR', 'Quadriceps-SMR', 'upper legs', 'quadriceps', '[]', 'foam roll', 'stretching', 'intermediate', '["Lay facedown on the floor with your weight supported by your hands or forearms. Place a foam roll underneath one leg on the quadriceps, and keep the foot off of the ground. Make sure to relax the leg as much as possible. This will be your starting position.","Shifting as much weight onto the leg to be stretched as is tolerable, roll over the foam from above the knee to below the hip, holding points of tension for 10-30 seconds. Switch sides."]', NULL, '["Quadriceps-SMR/0.jpg","Quadriceps-SMR/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Quick_Leap', 'Quick Leap', 'upper legs', 'quadriceps', '["calves","hamstrings"]', 'other', 'plyometrics', 'beginner', '["You will need a box for this exerise.","Begin facing the box standing 1-2 feet from its edge.","By utilizing your hips, hop onto the box, landing on both legs. Ensure that you land with your legs bent and your feet flat.","Immediately upon landing, fully extend through the entire body and swing your arms overhead to explode off of the box. Use your legs to absorb the impact of landing."]', NULL, '["Quick_Leap/0.jpg","Quick_Leap/1.jpg"]', 8, 'sets', 0, 'fedb', 1),
('fe-Rack_Delivery', 'Rack Delivery', 'shoulders', 'shoulders', '["forearms","traps"]', 'barbell', 'olympic weightlifting', 'intermediate', '["This drill teaches the delivery of the barbell to the rack position on the shoulders. Begin holding a bar in the scarecrow position, with the upper arms parallel to the floor, and the forearms hanging down. Use a hook grip, with your fingers wrapped over your thumbs.","Begin by rotating the elbows around the bar, delivering the bar to the shoulders. As your elbows come forward, relax your grip. The shoulders should be protracted, providing a shelf for the bar, which should lightly contact the throat.","It is important that the bar stay close to the body at all times, as with a heavier load any distance will result in an unwanted collision. As the movement becomes smoother, speed and load can be increased before progressing further."]', NULL, '["Rack_Delivery/0.jpg","Rack_Delivery/1.jpg"]', 6, 'sets', 0, 'fedb', 1),
('fe-Rack_Pull_with_Bands', 'Rack Pull with Bands', 'back', 'lower back', '["forearms","glutes","hamstrings","quadriceps","traps"]', 'barbell', 'powerlifting', 'intermediate', '["Set up in a power rack with the bar on the pins. The pins should be set to the desired point; just below the knees, just above, or in the mid thigh position. Attach bands to the base of the rack, or secure them with dumbbells. Attach the other end to the bar. You may need to choke the bands to provide tension.","Position yourself against the bar in proper deadlifting position. Your feet should be under your hips, your grip shoulder width, back arched, and hips back to engage the hamstrings. Since the weight is typically heavy, you may use a mixed grip, a hook grip, or use straps to aid in holding the weight.","With your head looking forward, extend through the hips and knees, pulling the weight up and back until lockout. Be sure to pull your shoulders back as you complete the movement. Return the weight to the pins and repeat."]', NULL, '["Rack_Pull_with_Bands/0.jpg","Rack_Pull_with_Bands/1.jpg"]', 6, 'sets', 0, 'fedb', 1),
('fe-Rack_Pulls', 'Rack Pulls', 'back', 'lower back', '["forearms","glutes","hamstrings","traps"]', 'barbell', 'powerlifting', 'intermediate', '["Set up in a power rack with the bar on the pins. The pins should be set to the desired point; just below the knees, just above, or in the mid thigh position. Position yourself against the bar in proper deadlifting position. Your feet should be under your hips, your grip shoulder width, back arched, and hips back to engage the hamstrings. Since the weight is typically heavy, you may use a mixed grip, a hook grip, or use straps to aid in holding the weight.","With your head looking forward, extend through the hips and knees, pulling the weight up and back until lockout. Be sure to pull your shoulders back as you complete the movement.","Return the weight to the pins and repeat."]', NULL, '["Rack_Pulls/0.jpg","Rack_Pulls/1.jpg"]', 6, 'sets', 0, 'fedb', 1),
('fe-Rear_Leg_Raises', 'Rear Leg Raises', 'upper legs', 'quadriceps', '[]', 'body only', 'stretching', 'beginner', '["Place yourself on your hands knees on an exercise mat. Your head should be looking forward and the bend of the knees should create a 90-degree angle between the hamstrings and the calves. This will be your starting position.","Extend one leg up and behind you. The knee and hip should both extend. Repeat for 5-10 repetitions, and then switch sides."]', NULL, '["Rear_Leg_Raises/0.jpg","Rear_Leg_Raises/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Recumbent_Bike', 'Recumbent Bike', 'cardio', 'quadriceps', '["calves","glutes","hamstrings"]', 'machine', 'cardio', 'beginner', '["To begin, seat yourself on the bike and adjust the seat to your height.","Select the desired option from the menu. You may have to start pedaling to turn it on. You can use the manual setting, or you can select a program to use. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. The level of resistance can be changed throughout the workout. The handles can be used to monitor your heart rate to help you stay at an appropriate intensity.","Recumbent bikes offer convenience, cardiovascular benefits, and have less impact than other activities. A 150 lb person will burn about 230 calories cycling at a moderate rate for 30 minutes, compared to 450 calories or more running."]', NULL, '["Recumbent_Bike/0.jpg","Recumbent_Bike/1.jpg"]', 7.5, 'time', 0, 'fedb', 1),
('fe-Return_Push_from_Stance', 'Return Push from Stance', 'shoulders', 'shoulders', '["chest","triceps"]', 'medicine ball', 'plyometrics', 'beginner', '["You will need a partner for this drill.","Begin in an athletic 2 or 3 point stance.","At the signal, move into a position to receive the pass from your partner.","Catch the medicine ball with both hands and immediately throw it back to your partner.","You can modify this drill by running different routes."]', NULL, '["Return_Push_from_Stance/0.jpg","Return_Push_from_Stance/1.jpg"]', 8, 'sets', 0, 'fedb', 1),
('fe-Reverse_Band_Bench_Press', 'Reverse Band Bench Press', 'upper arms', 'triceps', '["chest","forearms","lats","middle back","shoulders"]', 'barbell', 'powerlifting', 'intermediate', '["Position a bench inside a power rack, with the bar set to the correct height. Begin by anchoring bands either to band pegs or to the top of the rack. Ensure that you will be position properly under the bands. Attach the other end to the barbell.","Lie on the bench, tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this tight body position throughout the movement. However wide your grip, it should cover the ring on the bar.","Pull the bar out of the rack without protracting your shoulders. Focus on squeezing the bar and trying to pull it apart. Lower the bar to your lower chest or upper stomach. The bar, wrist, and elbow should stay in line at all times.","Pause when the barbell touches your torso, and then drive the bar up with as much force as possible. The elbows should be tucked in until lockout."]', NULL, '["Reverse_Band_Bench_Press/0.jpg","Reverse_Band_Bench_Press/1.jpg"]', 6, 'sets', 0, 'fedb', 1),
('fe-Reverse_Band_Box_Squat', 'Reverse Band Box Squat', 'upper legs', 'quadriceps', '["abductors","adductors","calves","forearms","glutes","hamstrings","lower back"]', 'barbell', 'powerlifting', 'intermediate', '["Begin in a power rack with a box at the appropriate height behind you. Set up the bands either on band pegs or attached to the top of the rack, ensuring they will be directly above the bar during the squat. Attach the other end to the bar.","Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wider for more emphasis on the back, glutes, adductors, and hamstrings, or closer together for more quad development. Keep your head facing forward.","With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips until you are seated on the box. Ideally, your shins should be perpendicular to the ground. Pause when you reach the box, and relax the hip flexors. Never bounce off of a box.","Keeping the weight on your heels and pushing your feet and knees out, drive upward off of the box as you lead the movement with your head. Continue upward, maintaining tightness head to toe. Use care to return the barbell to the rack."]', NULL, '["Reverse_Band_Box_Squat/0.jpg","Reverse_Band_Box_Squat/1.jpg"]', 6, 'sets', 0, 'fedb', 1),
('fe-Reverse_Band_Deadlift', 'Reverse Band Deadlift', 'back', 'lower back', '["abductors","adductors","calves","glutes","hamstrings","quadriceps"]', 'barbell', 'powerlifting', 'expert', '["Set the bar up in a power rack. Attach bands to the top of the rack, using either bands pegs or the frame itself. Attach the other end of the bands to the bar.","Approach the bar so that it is centered over your feet. You feet should be about hip width apart. Bend at the hip to grip the bar at shoulder width, allowing your shoulder blades to protract. Typically, you would use an overhand grip or an over/under grip on heavier sets.","With your feet, and your grip set, take a big breath and then lower your hips and bend the knees until your shins contact the bar. Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward.","After the bar passes the knees, aggressively pull the bar back, pulling your shoulder blades together as you drive your hips forward into the bar.","Lower the bar by bending at the hips and guiding it to the floor."]', NULL, '["Reverse_Band_Deadlift/0.jpg","Reverse_Band_Deadlift/1.jpg"]', 6, 'sets', 0, 'fedb', 1),
('fe-Reverse_Band_Power_Squat', 'Reverse Band Power Squat', 'upper legs', 'quadriceps', '["adductors","calves","glutes","hamstrings","lower back"]', 'barbell', 'powerlifting', 'expert', '["Begin in a power rack with the pins and bar set at the appropriate height. After loading the bar, attach bands to the top of the rack, using either pegs or the frame itself. Attach the other end of the bands to the bar.","Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wide for more emphasis on the back, glutes, adductors, and hamstrings.","Keep your head facing forward. With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips as much as possible. Ideally, your shins should be perpendicular to the ground. Lower bar position necessitates a greater torso lean to keep the bar over the heels. Continue until you break parallel, which is defined as the crease of the hip being in line with the top of the knee.","Keeping the weight on your heels and pushing your feet and knees out, drive upward as you lead the movement with your head. Continue upward, maintaining tightness head to toe, until you have returned to the starting position."]', NULL, '["Reverse_Band_Power_Squat/0.jpg","Reverse_Band_Power_Squat/1.jpg"]', 6, 'sets', 0, 'fedb', 1),
('fe-Reverse_Band_Sumo_Deadlift', 'Reverse Band Sumo Deadlift', 'upper legs', 'hamstrings', '["abductors","adductors","calves","forearms","glutes","lower back","quadriceps","traps"]', 'barbell', 'powerlifting', 'expert', '["Begin with a bar loaded on the floor inside of a power rack. Attach bands to the top of the rack, using either pegs or the frame itself. Attach the other end to the barbell.","Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should be directly below the shoulders, inside the legs, and you can use a pronated grip, a mixed grip, or hook grip. Relax the shoulders, which in effect lengthens your arms.","Take a breath, and then lower your hips, looking forward with your head with your chest up. Drive through the floor, spreading your feet apart, with your weight on the back half of your feet. Extend through the hips and knees.","As the bar passes through the knees, lean back and drive the hips into the bar, pulling your shoulder blades together.","Return the weight to the ground by bending at the hips and controlling the weight on the way down."]', NULL, '["Reverse_Band_Sumo_Deadlift/0.jpg","Reverse_Band_Sumo_Deadlift/1.jpg"]', 6, 'sets', 0, 'fedb', 1),
('fe-Reverse_Barbell_Preacher_Curls', 'Reverse Barbell Preacher Curls', 'upper arms', 'biceps', '["forearms"]', 'e-z curl bar', 'strength', 'intermediate', '["Grab an EZ-bar using a shoulder width and palms down (pronated) grip.","Now place the upper part of both arms on top of the preacher bench and have your arms extended. This will be your starting position.","As you exhale, use the biceps to curl the weight up until your biceps are fully contracted and the barbell is at shoulder height. Squeeze the biceps hard for a second at the contracted position.","As you breathe in, slowly lower the barbell until your upper arms are extended and the biceps is fully stretched.","Repeat for the recommended amount of repetitions."]', NULL, '["Reverse_Barbell_Preacher_Curls/0.jpg","Reverse_Barbell_Preacher_Curls/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Reverse_Flyes', 'Reverse Flyes', 'shoulders', 'shoulders', '[]', 'dumbbell', 'strength', 'beginner', '["To begin, lie down on an incline bench with the chest and stomach pressing against the incline. Have the dumbbells in each hand with the palms facing each other (neutral grip).","Extend the arms in front of you so that they are perpendicular to the angle of the bench. The legs should be stationary while applying pressure with the ball of your toes. This is the starting position.","Maintaining the slight bend of the elbows, move the weights out and away from each other (to the side) in an arc motion while exhaling. Tip: Try to squeeze your shoulder blades together to get the best results from this exercise.","The arms should be elevated until they are parallel to the floor.","Feel the contraction and slowly lower the weights back down to the starting position while inhaling.","Repeat for the recommended amount of repetitions."]', NULL, '["Reverse_Flyes/0.jpg","Reverse_Flyes/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Reverse_Flyes_With_External_Rotation', 'Reverse Flyes With External Rotation', 'shoulders', 'shoulders', '[]', 'dumbbell', 'strength', 'intermediate', '["To begin, lie down on an incline bench set at a 30-degree angle with the chest and stomach pressing against the incline.","Have the dumbbells in each hand with the palms facing down to the floor. Your arms should be in front of you so that they are perpendicular to the angle of the bench. Tip: Your elbows should have a slight bend. The legs should be stationary while applying pressure with the ball of your toes (your heels should not be touching the floor). This is the starting position.","Maintaining the slight bend of the elbows, move the weights out and away from each other in an arc motion while exhaling.","As you lift the weight, your wrist should externally rotate by 90-degrees so that you go from a palms down (pronated) grip to a palms facing each other (neutral) grip. Tip: Try to squeeze your shoulder blades together to get the best results from this exercise.","The arms should be elevated until they are level with the head.","Feel the contraction and slowly lower the weights back down to the starting position while inhaling.","Repeat for the recommended amount of repetitions."]', NULL, '["Reverse_Flyes_With_External_Rotation/0.jpg","Reverse_Flyes_With_External_Rotation/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Reverse_Grip_Bent-Over_Rows', 'Reverse Grip Bent-Over Rows', 'back', 'middle back', '["biceps","lats","shoulders"]', 'barbell', 'strength', 'intermediate', '["Stand erect while holding a barbell with a supinated grip (palms facing up).","Bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The barbell should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.","While keeping the torso stationary, lift the barbell as you breathe out, keeping the elbows close to the body and not doing any force with the forearm other than holding the weights. On the top contracted position, squeeze the back muscles and hold for a second.","Slowly lower the weight again to the starting position as you inhale.","Repeat for the recommended amount of repetitions."]', NULL, '["Reverse_Grip_Bent-Over_Rows/0.jpg","Reverse_Grip_Bent-Over_Rows/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Reverse_Grip_Triceps_Pushdown', 'Reverse Grip Triceps Pushdown', 'upper arms', 'triceps', '[]', 'cable', 'strength', 'beginner', '["Start by setting a bar attachment (straight or e-z) on a high pulley machine.","Facing the bar attachment, grab it with the palms facing up (supinated grip) at shoulder width. Lower the bar by using your lats until your arms are fully extended by your sides. Tip: Elbows should be in by your sides and your feet should be shoulder width apart from each other. This is the starting position.","Slowly elevate the bar attachment up as you inhale so it is aligned with your chest. Only the forearms should move and the elbows/upper arms should be stationary by your side at all times.","Then begin to lower the cable bar back down to the original staring position while exhaling and contracting the triceps hard.","Repeat for the recommended amount of repetitions."]', NULL, '["Reverse_Grip_Triceps_Pushdown/0.jpg","Reverse_Grip_Triceps_Pushdown/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Reverse_Hyperextension', 'Reverse Hyperextension', 'upper legs', 'hamstrings', '["calves","glutes"]', 'machine', 'strength', 'intermediate', '["Place your feet between the pads after loading an appropriate weight. Lay on the top pad, allowing your hips to hang off the back, while grasping the handles to hold your position.","To begin the movement, flex the hips, pulling the legs forward.","Reverse the motion by extending the hips, kicking the leg back. It is very important not to over-extend the hip on this movement, stopping short of your full range of motion.","Return by again flexing the hip, pulling the carriage forward as far as you can.","Repeat for the desired number of repetitions."]', NULL, '["Reverse_Hyperextension/0.jpg","Reverse_Hyperextension/1.jpg"]', 5, 'sets', 0, 'fedb', 1)
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('fe-Reverse_Machine_Flyes', 'Reverse Machine Flyes', 'shoulders', 'shoulders', '[]', 'machine', 'strength', 'beginner', '["Adjust the handles so that they are fully to the rear. Make an appropriate weight selection and adjust the seat height so the handles are at shoulder level. Grasp the handles with your hands facing inwards. This will be your starting position.","In a semicircular motion, pull your hands out to your side and back, contracting your rear delts.","Keep your arms slightly bent throughout the movement, with all of the motion occurring at the shoulder joint.","Pause at the rear of the movement, and slowly return the weight to the starting position."]', NULL, '["Reverse_Machine_Flyes/0.jpg","Reverse_Machine_Flyes/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Reverse_Plate_Curls', 'Reverse Plate Curls', 'upper arms', 'biceps', '["forearms"]', 'other', 'strength', 'beginner', '["Start by standing straight with a weighted plate held by both hands and arms fully extended. Use a pronated grip (palms facing down) and make sure your fingers grab the rough side of the plate while your thumb grabs the smooth side. Note: For the best results, grab the weighted plate at an 11:00 and 1:00 o''clock position.","Your feet should be shoulder width apart from each other and the weighted plate should be near the groin area. This is the starting position.","Slowly lift the plate up while keeping the elbows in and the upper arms stationary until your biceps and forearms touch while exhaling. The plate should be evenly aligned with your torso at this point.","Feel the contraction for a second and begin to lower the weight back down to the starting position while inhaling","Repeat for the recommended amount of repetitions."]', NULL, '["Reverse_Plate_Curls/0.jpg","Reverse_Plate_Curls/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Reverse_Triceps_Bench_Press', 'Reverse Triceps Bench Press', 'upper arms', 'triceps', '["chest","shoulders"]', 'barbell', 'strength', 'intermediate', '["Lie back on a flat bench. Using a close, supinated grip (around shoulder width), lift the bar from the rack and hold it straight over you with your arms locked extended in front of you and perpendicular to the floor. This will be your starting position.","As you breathe in, come down slowly until you feel the bar on your middle chest. Tip: Make sure that as opposed to a regular bench press, you keep the elbows close to the torso at all times in order to maximize triceps involvement.","After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your triceps muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.","Repeat the movement for the prescribed amount of repetitions.","When you are done, place the bar back in the rack."]', NULL, '["Reverse_Triceps_Bench_Press/0.jpg","Reverse_Triceps_Bench_Press/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Rhomboids-SMR', 'Rhomboids-SMR', 'back', 'middle back', '["traps"]', 'foam roll', 'stretching', 'intermediate', '["Lay down with your back on the floor. Place a foam roll underneath your upper back, and cross your arms in front of you, protracting your shoulders. This will be your starting position.","Raise your hips off of the ground, placing your weight onto the foam roll. Shift your weight to one side at a time, rolling over your middle and upper back. Pause at points of tension for 10-30 seconds."]', NULL, '["Rhomboids-SMR/0.jpg","Rhomboids-SMR/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Rickshaw_Carry', 'Rickshaw Carry', 'lower arms', 'forearms', '["abdominals","calves","glutes","hamstrings","lower back","quadriceps","traps"]', 'other', 'strongman', 'intermediate', '["Position the frame at the starting point, and load with the appropriate weight. Standing in the center of the frame, begin by gripping the handles and driving through your heels to lift the frame. Ensure your chest and head are up and your back is straight.","Immediately begin walking briskly with quick, controlled steps. Keep your chest up and head forward, and make sure you continue breathing. Bring the frame to the ground after you have reached the end point."]', NULL, '["Rickshaw_Carry/0.jpg","Rickshaw_Carry/1.jpg"]', 7, 'sets', 0, 'fedb', 1),
('fe-Rickshaw_Deadlift', 'Rickshaw Deadlift', 'upper legs', 'quadriceps', '["forearms","glutes","hamstrings","lower back","traps"]', 'other', 'strongman', 'intermediate', '["Load the frame with the desired weight. Center yourself between the handles. You feet should be about hip width apart. Bend at the hips to grip the handles, allowing your shoulder blades to protract.","With your feet and your grip set, take a big breath and then lower your hips and flex the knees. Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward. As the weight comes up, pull your shoulder blades together as you drive your hips forward.","Lower the weight by bending at the hips and guiding it to the ground."]', NULL, '["Rickshaw_Deadlift/0.jpg","Rickshaw_Deadlift/1.jpg"]', 7, 'sets', 0, 'fedb', 1),
('fe-Ring_Dips', 'Ring Dips', 'upper arms', 'triceps', '["chest","shoulders"]', 'other', 'strength', 'intermediate', '["Grip a ring in each hand, and then take a small jump to help you get into the starting position with your arms locked out.","Begin by flexing the elbow, lowering your body until your arms break 90 degrees. Avoid swinging, and maintain good posture throughout the descent.","Reverse the motion by extending the elbow, pushing yourself back up into the starting position.","Repeat for the desired number of repetitions."]', NULL, '["Ring_Dips/0.jpg","Ring_Dips/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Rocket_Jump', 'Rocket Jump', 'upper legs', 'quadriceps', '["calves","hamstrings"]', 'body only', 'plyometrics', 'beginner', '["Begin in a relaxed stance with your feet shoulder width apart and hold your arms close to the body.","To initiate the move, squat down halfway and explode back up as high as possible.","Fully extend your entire body, reaching overhead as far as possible. As you land, absorb your impact through the legs."]', NULL, '["Rocket_Jump/0.jpg","Rocket_Jump/1.jpg"]', 8, 'sets', 0, 'fedb', 1),
('fe-Rocking_Standing_Calf_Raise', 'Rocking Standing Calf Raise', 'lower legs', 'calves', '[]', 'barbell', 'strength', 'beginner', '["This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place it on the back of your shoulders (slightly below the neck).","Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.","Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance. Also maintain a straight back and keep the knees with a slight bend; never locked. This will be your starting position.","Raise your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending (other than the slight initial bend we created during positioning) at any time. Hold the contracted position by a second before you start to go back down.","Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.","Now lift your toes by contracting the tibia muscles in the front of the calves as you breathe out.","Hold for a second and bring them back down as you breathe in.","Repeat for the recommended amount of repetitions."]', NULL, '["Rocking_Standing_Calf_Raise/0.jpg","Rocking_Standing_Calf_Raise/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Rocky_Pull-Ups_Pulldowns', 'Rocky Pull-Ups/Pulldowns', 'back', 'lats', '["biceps","middle back","shoulders"]', 'other', 'strength', 'intermediate', '["Grab the pull-up bar with the palms facing forward using a wide grip.","As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.","Pull your torso up until the bar touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of the movement. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.","After a second on the contracted position, start to inhale and slowly lower your torso back to the starting position when your arms are fully extended and the lats are fully stretched.","Now repeat the same movements as described above except this time your torso will remain straight as you go up and the bar will touch the back of the neck instead of the upper chest. Tip: Use the head to lean forward slightly as it will help you properly execute this portion of the exercise.","Once you have lowered yourself back down to the starting position, repeat the exercise for the prescribed amount of repetitions in your program."]', NULL, '["Rocky_Pull-Ups_Pulldowns/0.jpg","Rocky_Pull-Ups_Pulldowns/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Romanian_Deadlift', 'Romanian Deadlift', 'upper legs', 'hamstrings', '["calves","glutes","lower back"]', 'barbell', 'strength', 'intermediate', '["Put a barbell in front of you on the ground and grab it using a pronated (palms facing down) grip that a little wider than shoulder width. Tip: Depending on the weight used, you may need wrist wraps to perform the exercise and also a raised platform in order to allow for better range of motion.","Bend the knees slightly and keep the shins vertical, hips back and back straight. This will be your starting position.","Keeping your back and arms completely straight at all times, use your hips to lift the bar as you exhale. Tip: The movement should not be fast but steady and under control.","Once you are standing completely straight up, lower the bar by pushing the hips back, only slightly bending the knees, unlike when squatting. Tip: Take a deep breath at the start of the movement and keep your chest up. Hold your breath as you lower and exhale as you complete the movement.","Repeat for the recommended amount of repetitions."]', NULL, '["Romanian_Deadlift/0.jpg","Romanian_Deadlift/1.jpg"]', 5, 'sets', 1, 'fedb', 1),
('fe-Romanian_Deadlift_from_Deficit', 'Romanian Deadlift from Deficit', 'upper legs', 'hamstrings', '["forearms","glutes","lower back","traps"]', 'barbell', 'olympic weightlifting', 'intermediate', '["Begin standing while holding a bar at arm''s length in front of you. You can stand on a raised platform to increase the range of motion.","Begin by flexing the knees slightly, and then flex at the hip, moving your butt back as far as possible, lowering the torso as far as flexibility allows. The back should remain in absolute extension at all times, and the bar should remain in contact with the legs. If done properly, there should be heavy tension felt in the hamstrings.","Reverse the motion to return to the starting position."]', NULL, '["Romanian_Deadlift_from_Deficit/0.jpg","Romanian_Deadlift_from_Deficit/1.jpg"]', 6, 'sets', 0, 'fedb', 1),
('fe-Rope_Climb', 'Rope Climb', 'back', 'lats', '["biceps","forearms","middle back","shoulders"]', 'other', 'strength', 'intermediate', '["Grab the rope with both hands above your head. Pull down on the rope as you take a small jump.","Wrap the rope around one leg, using your feet to pinch the rope. Reach up as high as possible with your arms, gripping the rope tightly.","Release the rope from your feet as you pull yourself up with your arms, bringing your knees towards your chest.","Resecure your feet on the rope, and then stand up to take another high hold on the rope. Continue until you reach the top of the rope.","To lower yourself, loosen the grip of your feet on the rope as you slide down using a hand over hand motion."]', NULL, '["Rope_Climb/0.jpg","Rope_Climb/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Rope_Crunch', 'Rope Crunch', 'waist', 'abdominals', '[]', 'cable', 'strength', 'beginner', '["Kneel 1-2 feet in front of a cable system with a rope attached.","After selecting an appropriate weight, grasp the rope with both hands reaching overhead. Your torso should be upright in the starting position.","To begin, flex at the spine, attempting to bring your rib cage to your legs as you pull the cable down.","Pause at the bottom of the motion, and then slowly return to the starting position.","These can be done with twists or to the side to hit the obliques."]', NULL, '["Rope_Crunch/0.jpg","Rope_Crunch/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Rope_Jumping', 'Rope Jumping', 'cardio', 'quadriceps', '["calves","hamstrings"]', 'other', 'cardio', 'intermediate', '["Hold an end of the rope in each hand. Position the rope behind you on the ground. Raise your arms up and turn the rope over your head bringing it down in front of you. When it reaches the ground, jump over it. Find a good turning pace that can be maintained. Different speeds and techniques can be used to introduce variation.","Rope jumping is exciting, challenges your coordination, and requires a lot of energy. A 150 lb person will burn about 350 calories jumping rope for 30 minutes, compared to over 450 calories running."]', NULL, '["Rope_Jumping/0.jpg","Rope_Jumping/1.jpg"]', 11, 'time', 0, 'fedb', 1),
('fe-Rope_Straight-Arm_Pulldown', 'Rope Straight-Arm Pulldown', 'back', 'lats', '[]', 'cable', 'strength', 'beginner', '["Attach a rope to a high pulley and make your weight selection. Stand a couple feet back from the pulley with your feet staggered and take the rope with both hands. Lean forward from the hip, keeping your back straight, with your arms extended up in front of you. This will be your starting position.","Keeping your arms straight, extend the shoulder to pull the rope down to your thighs.","Pause at the bottom of the motion, squeezing your lats.","Return to the starting position without allowing the weight to fully rest on the stack."]', NULL, '["Rope_Straight-Arm_Pulldown/0.jpg","Rope_Straight-Arm_Pulldown/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Round_The_World_Shoulder_Stretch', 'Round The World Shoulder Stretch', 'shoulders', 'shoulders', '["biceps","chest"]', 'other', 'stretching', 'beginner', '["Stand up straight with your legs together, holding a bodybar or broomstick.","Hold the pole behind your hips with a wider than shoulder width grip. Your palms should be down and your thumbs facing out.","Slowly lift your arms up behind your head. Don''t force it if it gets hard to lift further."]', NULL, '["Round_The_World_Shoulder_Stretch/0.jpg","Round_The_World_Shoulder_Stretch/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Rowing_Stationary', 'Rowing, Stationary', 'cardio', 'quadriceps', '["biceps","calves","glutes","hamstrings","lower back","middle back"]', 'machine', 'cardio', 'intermediate', '["To begin, seat yourself on the rower. Make sure that your heels are resting comfortably against the base of the foot pedals and that the straps are secured. Select the program that you wish to use, if applicable. Sit up straight and bend forward at the hips.","There are three phases of movement when using a rower. The first phase is when you come forward on the rower. Your knees are bent and against your chest. Your upper body is leaning slightly forward while still maintaining good posture. Next, push against the foot pedals and extend your legs while bringing your hands to your upper abdominal area, squeezing your shoulders back as you do so. To avoid straining your back, use primarily your leg and hip muscles.","The recovery phase simply involves straightening your arms, bending the knees, and bringing your body forward again as you transition back into the first phase."]', NULL, '["Rowing_Stationary/0.jpg","Rowing_Stationary/1.jpg"]', 7, 'time', 0, 'fedb', 1),
('fe-Runners_Stretch', 'Runner''s Stretch', 'upper legs', 'hamstrings', '["calves"]', 'body only', 'stretching', 'beginner', '["It''s easiest to get into this stretch if you start standing up, put one leg behind you, and slowly lower your torso down to the floor.","Keep the front heel on the floor (if it lifts up, scoot your other leg further back).","Place your hands on either side of your front leg. To get more out of this stretch, push your butt up toward the ceiling, and then gradually lower it back toward the floor. You''ll Stretch the hip flexor of the back leg and the hamstring and buttocks of the front."]', NULL, '["Runners_Stretch/0.jpg","Runners_Stretch/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Running_Treadmill', 'Running, Treadmill', 'cardio', 'quadriceps', '["calves","glutes","hamstrings"]', 'machine', 'cardio', 'beginner', '["To begin, step onto the treadmill and select the desired option from the menu. Most treadmills have a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. Elevation can be adjusted to change the intensity of the workout.","Treadmills offer convenience, cardiovascular benefits, and usually have less impact than running outside. A 150 lb person will burn over 450 calories running 8 miles per hour for 30 minutes. Maintain proper posture as you run, and only hold onto the handles when necessary, such as when dismounting or checking your heart rate."]', NULL, '["Running_Treadmill/0.jpg","Running_Treadmill/1.jpg"]', 9.8, 'time', 0, 'fedb', 1),
('fe-Sandbag_Load', 'Sandbag Load', 'upper legs', 'quadriceps', '["abdominals","biceps","calves","forearms","glutes","hamstrings","lower back","middle back","shoulders","traps"]', 'other', 'strongman', 'beginner', '["To load sandbags or other objects, begin with the implements placed a distance from the loading platform, typically 50 feet.","Begin by lifting the sandbag. Sandbags are extremely awkward, and the manner of lifting them can vary depending on the particular sandbag used. Reach as far around it as possible, extending through the hips and knees to pull it up high. Shouldering is usually not allowed.","Move as quickly as possible to the platform, and load it, extending through your hips, knees, and ankles to get it as high as possible. Place it onto the platform, ensuring it doesn''t fall off.","Return to the starting position to retrieve the next sandbag, and repeat until the event is completed."]', NULL, '["Sandbag_Load/0.jpg","Sandbag_Load/1.jpg"]', 7, 'sets', 0, 'fedb', 1),
('fe-Scapular_Pull-Up', 'Scapular Pull-Up', 'back', 'traps', '["lats","middle back"]', 'body only', 'strength', 'beginner', '["Take a pronated grip on a pull-up bar.","From a hanging position, raise yourself a few inches without using your arms. Do this by depressing your shoulder girdle in a reverse shrugging motion.","Pause at the completion of the movement, and then slowly return to the starting position before performing more repetitions."]', NULL, '["Scapular_Pull-Up/0.jpg","Scapular_Pull-Up/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Scissor_Kick', 'Scissor Kick', 'waist', 'abdominals', '[]', 'body only', 'stretching', 'beginner', '["To begin, lie down with your back pressed against the floor or on an exercise mat (optional). Your arms should be fully extended to the sides with your palms facing down. Note: The arms should be stationary the entire time.","With a slight bend at the knees, lift your legs up so that your heels are about 6 inches off the ground. This is the starting position.","Now lift your left leg up to about a 45 degree angle while your right leg is lowered until the heel is about 2-3 inches from the ground.","Switch movements by raising your right leg up and lowering your left leg. Remember to breathe while performing this exercise.","Repeat for the recommended amount of repetitions."]', NULL, '["Scissor_Kick/0.jpg","Scissor_Kick/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Scissors_Jump', 'Scissors Jump', 'upper legs', 'quadriceps', '["glutes","hamstrings"]', 'body only', 'plyometrics', 'beginner', '["Assume a lunge stance position with one foot forward with the knee bent, and the rear knee nearly touching the ground.","Ensure that the front knee is over the midline of the foot. Extending through both legs, jump as high as possible, swinging your arms to gain lift.","As you jump as high as you can, switch the position of your legs, moving your front leg to the back and the rear leg to the front.","As you land, absorb the impact through the legs by adopting the lunge position, and repeat."]', NULL, '["Scissors_Jump/0.jpg","Scissors_Jump/1.jpg"]', 8, 'sets', 0, 'fedb', 1),
('fe-Seated_Band_Hamstring_Curl', 'Seated Band Hamstring Curl', 'upper legs', 'hamstrings', '[]', 'other', 'strength', 'beginner', '["Secure a band close to the ground and place a bench a couple feet away from it.","Seat yourself on the bench and secure the band behind your ankles, beginning with your legs straight. This will be your starting position.","Flex the knees, bringing your feet towards the bench. You may need to lean back slightly to keep your feet from striking the floor.","Pause at the completion of the movement, and then slowly return to the starting position."]', NULL, '["Seated_Band_Hamstring_Curl/0.jpg","Seated_Band_Hamstring_Curl/1.jpg"]', 5, 'sets', 0, 'fedb', 1)
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('fe-Seated_Barbell_Military_Press', 'Seated Barbell Military Press', 'shoulders', 'shoulders', '["triceps"]', 'barbell', 'strength', 'intermediate', '["Sit on a Military Press Bench with a bar behind your head and either have a spotter give you the bar (better on the rotator cuff this way) or pick it up yourself carefully with a pronated grip (palms facing forward). Tip: Your grip should be wider than shoulder width and it should create a 90-degree angle between the forearm and the upper arm as the barbell goes down.","Once you pick up the barbell with the correct grip length, lift the bar up over your head by locking your arms. Hold at about shoulder level and slightly in front of your head. This is your starting position.","Lower the bar down to the collarbone slowly as you inhale.","Lift the bar back up to the starting position as you exhale.","Repeat for the recommended amount of repetitions."]', NULL, '["Seated_Barbell_Military_Press/0.jpg","Seated_Barbell_Military_Press/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Seated_Bent-Over_One-Arm_Dumbbell_Triceps_Extension', 'Seated Bent-Over One-Arm Dumbbell Triceps Extension', 'upper arms', 'triceps', '[]', 'dumbbell', 'strength', 'beginner', '["Sit down at the end of a flat bench with a dumbbell in one arm using a neutral grip (palms of the hand facing you).","Bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Make sure that you keep the head up.","The upper arm with the dumbbell should be close to the torso and aligned with it (lifted up until it is parallel to the floor while the forearms are pointing towards the floor as the hands hold the weights). Tip: There should be a 90-degree angle between the forearms and the upper arm. This is your starting position.","Keeping the upper arm stationary, use the triceps to lift the weight as you exhale until the forearm is parallel to the floor and the whole arm is extended. Like many other arm exercises, only the forearm moves.","After a second contraction at the top, slowly lower the dumbbell back to the starting position as you inhale.","Repeat the movement for the prescribed amount of repetitions.","Switch arms and repeat the exercise."]', NULL, '["Seated_Bent-Over_One-Arm_Dumbbell_Triceps_Extension/0.jpg","Seated_Bent-Over_One-Arm_Dumbbell_Triceps_Extension/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Seated_Bent-Over_Rear_Delt_Raise', 'Seated Bent-Over Rear Delt Raise', 'shoulders', 'shoulders', '[]', 'dumbbell', 'strength', 'intermediate', '["Place a couple of dumbbells looking forward in front of a flat bench.","Sit on the end of the bench with your legs together and the dumbbells behind your calves.","Bend at the waist while keeping the back straight in order to pick up the dumbbells. The palms of your hands should be facing each other as you pick them. This will be your starting position.","Keeping your torso forward and stationary, and the arms slightly bent at the elbows, lift the dumbbells straight to the side until both arms are parallel to the floor. Exhale as you lift the weights. (Note: avoid swinging the torso or bringing the arms back as opposed to the side.)","After a one second contraction at the top, slowly lower the dumbbells back to the starting position.","Repeat for the recommended amount of repetitions."]', NULL, '["Seated_Bent-Over_Rear_Delt_Raise/0.jpg","Seated_Bent-Over_Rear_Delt_Raise/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Seated_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension', 'Seated Bent-Over Two-Arm Dumbbell Triceps Extension', 'upper arms', 'triceps', '[]', 'dumbbell', 'strength', 'intermediate', '["Sit down at the end of a flat bench with a dumbbell in both arms using a neutral grip (palms of the hand facing you).","Bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Make sure that you keep the head up.","The upper arms with the dumbbells should be close to the torso and aligned with it (lifted up until they are parallel to the floor while the forearms are pointing towards the floor as the hands hold the weights). Tip: There should be a 90-degree angle between the forearms and the upper arm. This is your starting position.","Keeping the upper arms stationary, use the triceps to lift the weight as you exhale until the forearms are parallel to the floor and the whole arm is extended. Like many other arm exercises, only the forearm moves.","After a second contraction at the top, slowly lower the dumbbells back to the starting position as you inhale.","Repeat the movement for the prescribed amount of repetitions."]', NULL, '["Seated_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension/0.jpg","Seated_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Seated_Biceps', 'Seated Biceps', 'upper arms', 'biceps', '["chest","shoulders"]', 'body only', 'stretching', 'expert', '["Sit on the floor with your knees bent and your partner standing behind you. Extend your arms straight behind you with your palms facing each other. Your partner will hold your wrists for you. This will be the starting position.","Attempt to flex your elbows, while your partner prevents any actual movement.","After 10-20 seconds, relax your arms while your partner gently pulls your wrists up to stretch your biceps. Be sure to let your partner know when the stretch is appropriate to prevent injury or overstretching."]', NULL, '["Seated_Biceps/0.jpg","Seated_Biceps/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Seated_Cable_Shoulder_Press', 'Seated Cable Shoulder Press', 'shoulders', 'shoulders', '["triceps"]', 'cable', 'strength', 'beginner', '["Adjust the weight to an appropriate amount and be seated, grasping the handles. Your upper arms should be about 90 degrees to the body, with your head and chest up. The elbows should also be bent to about 90 degrees. This will be your starting position.","Begin by extending through the elbow, pressing the handles together above your head.","After pausing at the top, return the handles to the starting position. Ensure that you maintain tension on the cables.","You can also execute this movement with your back off the pad and alternate hands."]', NULL, '["Seated_Cable_Shoulder_Press/0.jpg","Seated_Cable_Shoulder_Press/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Seated_Calf_Raise', 'Seated Calf Raise', 'lower legs', 'calves', '[]', 'machine', 'strength', 'beginner', '["Sit on the machine and place your toes on the lower portion of the platform provided with the heels extending off. Choose the toe positioning of your choice (forward, in, or out) as per the beginning of this chapter.","Place your lower thighs under the lever pad, which will need to be adjusted according to the height of your thighs. Now place your hands on top of the lever pad in order to prevent it from slipping forward.","Lift the lever slightly by pushing your heels up and release the safety bar. This will be your starting position.","Slowly lower your heels by bending at the ankles until the calves are fully stretched. Inhale as you perform this movement.","Raise the heels by extending the ankles as high as possible as you contract the calves and breathe out. Hold the top contraction for a second.","Repeat for the recommended amount of repetitions."]', NULL, '["Seated_Calf_Raise/0.jpg","Seated_Calf_Raise/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Seated_Calf_Stretch', 'Seated Calf Stretch', 'lower legs', 'calves', '["hamstrings","lower back"]', 'body only', 'stretching', 'beginner', '["Sit up straight on an exercise mat.","Bend one knee and put that foot on the floor to stabilize the torso.","Straighten your other leg and flex your ankle.","Using a band, towel, or your hand if you can reach, pull the toes toward you. Hold for 10 to 20 seconds, then switch sides."]', NULL, '["Seated_Calf_Stretch/0.jpg","Seated_Calf_Stretch/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Seated_Dumbbell_Palms-Down_Wrist_Curl', 'Seated Dumbbell Palms-Down Wrist Curl', 'lower arms', 'forearms', '[]', 'dumbbell', 'strength', 'beginner', '["Start out by placing two dumbbells on the floor in front of a flat bench.","Sit down on the edge of the flat bench with your legs at about shoulder width apart. Make sure to keep your feet on the floor.","Use your arms to grab both of the dumbbells and bring them up so that your forearms are resting against your thighs with the palms of the hands facing down. Your wrists should be hanging over the edge of your thighs.","Start out by curling your wrist upwards and exhaling.","Slowly lower your wrists back down to the starting position while inhaling. Make sure to inhale during this part of the exercise. Tip: Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.","Repeat for the recommended amount of repetitions.","When finished, simply lower the dumbbells to the floor."]', NULL, '["Seated_Dumbbell_Palms-Down_Wrist_Curl/0.jpg","Seated_Dumbbell_Palms-Down_Wrist_Curl/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Seated_Flat_Bench_Leg_Pull-In', 'Seated Flat Bench Leg Pull-In', 'waist', 'abdominals', '[]', 'body only', 'strength', 'beginner', '["Sit on a bench with the legs stretched out in front of you slightly below parallel and your arms holding on to the sides of the bench. Your torso should be leaning backwards around a 45-degree angle from the bench. This will be your starting position.","Bring the knees in toward you as you move your torso closer to them at the same time. Breathe out as you perform this movement.","After a second pause, go back to the starting position as you inhale.","Repeat for the recommended amount of repetitions."]', NULL, '["Seated_Flat_Bench_Leg_Pull-In/0.jpg","Seated_Flat_Bench_Leg_Pull-In/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Seated_Floor_Hamstring_Stretch', 'Seated Floor Hamstring Stretch', 'upper legs', 'hamstrings', '["calves"]', 'body only', 'stretching', 'beginner', '["Sit on a mat with your right leg extended in front of you and your left leg bent with your foot against your right inner thigh.","Lean forward from your hips and reach for your ankle until you feel a stretch in your hamstring. Hold for 15 seconds, then repeat for your other side."]', NULL, '["Seated_Floor_Hamstring_Stretch/0.jpg","Seated_Floor_Hamstring_Stretch/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Seated_Front_Deltoid', 'Seated Front Deltoid', 'shoulders', 'shoulders', '["chest"]', 'body only', 'stretching', 'expert', '["Sit upright on the floor with your legs bent, your partner standing behind you. Stick your arms straight out to your sides, with your palms facing the ground. Attempt to move them as far behind you as possible, as your assistant holds your wrists. This will be your starting position.","Keeping your elbows straight, attempt to move your arms to the front, with your partner gently restraining you to prevent any actual movement for 10-20 seconds.","Now, relax your muscles and allow your partner to gently increase the stretch on the shoulders and chest. Hold for 10 to 20 seconds."]', NULL, '["Seated_Front_Deltoid/0.jpg","Seated_Front_Deltoid/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Seated_Glute', 'Seated Glute', 'upper legs', 'glutes', '["adductors"]', 'body only', 'stretching', 'expert', '["In a seated position with your knees bent, cross one ankle over the opposite knee. Your partner will stand behind you. Now, lean forward as your partner braces your shoulders with their hands. This will be your starting position.","Attempt to push your torso back for 10-20 seconds, as your partner prevents any actual movement of your torso.","Now relax your muscles as your partner increases the stretch by gently pushing your torso forward for 10-20 seconds."]', NULL, '["Seated_Glute/0.jpg","Seated_Glute/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Seated_Good_Mornings', 'Seated Good Mornings', 'back', 'lower back', '["glutes"]', 'barbell', 'powerlifting', 'intermediate', '["Set up a box in a power rack. The pins should be set at an appropriate height. Begin by stepping under the bar and placing it across the back of the shoulders, not on top of your traps. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders.","Remove the bar from the rack, creating a tight arch in your lower back. Keep your head facing forward. With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips until you are seated on the box. This will be your starting position.","Keeping the bar tight, bend forward at the hips as much as possible. If you set the pins to what would be parallel, you not only have a safety if you fail, but know when to stop.","Pause just above the pins and reverse the motion until your torso it upright."]', NULL, '["Seated_Good_Mornings/0.jpg","Seated_Good_Mornings/1.jpg"]', 6, 'sets', 0, 'fedb', 1),
('fe-Seated_Hamstring', 'Seated Hamstring', 'upper legs', 'hamstrings', '["calves"]', 'body only', 'stretching', 'expert', '["In a seated position with your legs extended, have your partner stand behind you. Now, lean forward as your partner braces your shoulders with their hands. This will be your starting position.","Attempt to push your torso back for 10-20 seconds, as your partner prevents any actual movement of your torso.","Now relax your muscles as your partner increases the stretch by gently pushing your torso forward for 10-20 seconds."]', NULL, '["Seated_Hamstring/0.jpg","Seated_Hamstring/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Seated_Hamstring_and_Calf_Stretch', 'Seated Hamstring and Calf Stretch', 'upper legs', 'hamstrings', '["calves"]', 'other', 'stretching', 'intermediate', '["Loop a belt, rope, or band around one foot. Sit down with both legs extended . This will be your starting position.","Leaning forward slightly, pull on the belt to draw the toes of your foot back. Hold this position for 10-20 seconds and then repeat with the other leg."]', NULL, '["Seated_Hamstring_and_Calf_Stretch/0.jpg","Seated_Hamstring_and_Calf_Stretch/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Seated_Head_Harness_Neck_Resistance', 'Seated Head Harness Neck Resistance', 'neck', 'neck', '[]', 'other', 'strength', 'intermediate', '["Place a neck strap on the floor at the end of a flat bench. Once you have selected the weights, sit at the end of the flat bench with your feet wider than shoulder width apart from each other. Your toes should be pointed out.","Slowly move your torso forward until it is almost parallel with the floor. Using both hands, securely position the neck strap around your head. Tip: Make sure the weights are still lying on the floor to prevent any strain on the neck. Now grab the weight with both hands while elevating your torso back until it is almost perpendicular to the floor. Note: Your head and torso needs to be slightly tilted forward to perform this exercise.","Now place both hands on top of your knees. This is the starting position.","Slowly lower your neck down until your chin touches the upper part of your chest while breathing in.","While exhaling, bring your neck back to the starting position.","Repeat for the recommended amount of repetitions."]', NULL, '["Seated_Head_Harness_Neck_Resistance/0.jpg","Seated_Head_Harness_Neck_Resistance/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Seated_Leg_Curl', 'Seated Leg Curl', 'upper legs', 'hamstrings', '[]', 'machine', 'strength', 'beginner', '["Adjust the machine lever to fit your height and sit on the machine with your back against the back support pad.","Place the back of lower leg on top of padded lever (just a few inches under the calves) and secure the lap pad against your thighs, just above the knees. Then grasp the side handles on the machine as you point your toes straight (or you can also use any of the other two stances) and ensure that the legs are fully straight right in front of you. This will be your starting position.","As you exhale, pull the machine lever as far as possible to the back of your thighs by flexing at the knees. Keep your torso stationary at all times. Hold the contracted position for a second.","Slowly return to the starting position as you breathe in.","Repeat for the recommended amount of repetitions."]', NULL, '["Seated_Leg_Curl/0.jpg","Seated_Leg_Curl/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Seated_Leg_Tucks', 'Seated Leg Tucks', 'waist', 'abdominals', '[]', 'body only', 'strength', 'beginner', '["Sit on a bench with the legs stretched out in front of you slightly below parallel and your arms holding on to the sides of the bench. Your torso should be leaning backwards around a 45-degree angle from the bench. This will be your starting position.","Bring the knees in toward you as you move your torso closer to them at the same time. Breathe out as you perform this movement.","After a second pause, go back to the starting position as you inhale.","Repeat for the recommended amount of repetitions."]', NULL, '["Seated_Leg_Tucks/0.jpg","Seated_Leg_Tucks/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Seated_One-Arm_Dumbbell_Palms-Down_Wrist_Curl', 'Seated One-Arm Dumbbell Palms-Down Wrist Curl', 'lower arms', 'forearms', '[]', 'dumbbell', 'strength', 'intermediate', '["Sit on a flat bench with a dumbbell in your right hand.","Place your feet flat on the floor, at a distance that is slightly wider than shoulder width apart.","Lean forward and place your right forearm on top of your upper right thigh with your palm down. Tip: Make sure that the back of the wrist lies on top of your knees. This will be your starting position.","Lower the dumbbell as far as possible as you keep a tight grip on the dumbbell. Inhale as you perform this movement.","Now curl the dumbbell as high as possible as you contract the forearms and as you exhale. Keep the contraction for a second before you lower again. Tip: The only movement should happen at the wrist.","Perform for the recommended amount of repetitions, switch arms and repeat the movement."]', NULL, '["Seated_One-Arm_Dumbbell_Palms-Down_Wrist_Curl/0.jpg","Seated_One-Arm_Dumbbell_Palms-Down_Wrist_Curl/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Seated_One-Arm_Dumbbell_Palms-Up_Wrist_Curl', 'Seated One-Arm Dumbbell Palms-Up Wrist Curl', 'lower arms', 'forearms', '[]', 'dumbbell', 'strength', 'beginner', '["Sit on a flat bench with a dumbbell in your right hand.","Place your feet flat on the floor, at a distance that is slightly wider than shoulder width apart.","Lean forward and place your right forearm on top of your upper right thigh with your palm up. Tip: Make sure that the front of the wrist lies on top of your knees. This will be your starting position.","Lower the dumbbell as far as possible as you keep a tight grip on the dumbbell. Inhale as you perform this movement.","Now curl the dumbbell as high as possible as you contract the forearms and as you exhale. Keep the contraction for a second before you lower again. Tip: The only movement should happen at the wrist.","Perform for the recommended amount of repetitions, switch arms and repeat the movement."]', NULL, '["Seated_One-Arm_Dumbbell_Palms-Up_Wrist_Curl/0.jpg","Seated_One-Arm_Dumbbell_Palms-Up_Wrist_Curl/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Seated_One-arm_Cable_Pulley_Rows', 'Seated One-arm Cable Pulley Rows', 'back', 'middle back', '["biceps","lats","traps"]', 'cable', 'strength', 'intermediate', '["To get into the starting position, first sit down on the machine and place your feet on the front platform or crossbar provided making sure that your knees are slightly bent and not locked.","Lean over as you keep the natural alignment of your back and grab the single handle attachment with your left arm using a palms-down grip.","With your arm extended pull back until your torso is at a 90-degree angle from your legs. Your back should be slightly arched and your chest should be sticking out. You should be feeling a nice stretch on your lat as you hold the bar in front of you. The right arm can be kept by the waist. This is the starting position of the exercise.","Keeping the torso stationary, pull the handles back towards your torso while keeping the arms close to it as you rotate the wrist, so that by the time your hand is by your abdominals it is in a neutral position (palms facing the torso). Breathe out as you perform that movement. At that point you should be squeezing your back muscles hard.","Hold that contraction for a second and slowly go back to the original position while breathing in. Tip: Remember to rotate the wrist as you go back to the starting position so that the palms are facing down again.","Repeat for the recommended amount of repetitions and then perform the same movement with the right hand."]', NULL, '["Seated_One-arm_Cable_Pulley_Rows/0.jpg","Seated_One-arm_Cable_Pulley_Rows/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Seated_Overhead_Stretch', 'Seated Overhead Stretch', 'waist', 'abdominals', '[]', 'body only', 'stretching', 'beginner', '["Sit up straight on an exercise mat.","Touch the soles of your feet together with your feet six to eight inches in front of your hips.","Place one hand on the floor beside you and your other hand behind your head.","Lift your elbow to the ceiling as you incline your torso to the other side. Hold for 10 to 20 seconds, then switch sides."]', NULL, '["Seated_Overhead_Stretch/0.jpg","Seated_Overhead_Stretch/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Seated_Palm-Up_Barbell_Wrist_Curl', 'Seated Palm-Up Barbell Wrist Curl', 'lower arms', 'forearms', '[]', 'barbell', 'strength', 'beginner', '["Hold a barbell with both hands and your palms facing up; hands spaced about shoulder width.","Place your feet flat on the floor, at a distance that is slightly wider than shoulder width apart.","Lean forward and place your forearms on top of your upper thighs with your palms up. Tip: Make sure that the front of the wrists lay on top of your knees. This will be your starting position.","Lower the bar as far as possible while inhaling and keeping a tight grip.","Now curl bar up as high as possible while flexing the forearms and exhaling. Hold the contraction at the top for a second and Tip: Only the wrist should move."]', NULL, '["Seated_Palm-Up_Barbell_Wrist_Curl/0.jpg","Seated_Palm-Up_Barbell_Wrist_Curl/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Seated_Palms-Down_Barbell_Wrist_Curl', 'Seated Palms-Down Barbell Wrist Curl', 'lower arms', 'forearms', '[]', 'barbell', 'strength', 'beginner', '["Hold a barbell with both hands and your palms facing down; hands spaced about shoulder width.","Place your feet flat on the floor, at a distance that is slightly wider than shoulder width apart.","Lean forward and place your forearms on top of your upper thighs with your palms down. Tip: Make sure that the back of the wrists lay on top of your knees. This will be your starting position.","Lower the bar as far as possible while inhaling and keeping a tight grip.","Now curl bar up as high as possible while flexing the forearms and exhaling. Hold the contraction at the top for a second and Tip: Only the wrist should move."]', NULL, '["Seated_Palms-Down_Barbell_Wrist_Curl/0.jpg","Seated_Palms-Down_Barbell_Wrist_Curl/1.jpg"]', 5, 'sets', 0, 'fedb', 1)
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('fe-Seated_Side_Lateral_Raise', 'Seated Side Lateral Raise', 'shoulders', 'shoulders', '[]', 'dumbbell', 'strength', 'beginner', '["Pick a couple of dumbbells and sit at the end of a flat bench with your feet firmly on the floor. Hold the dumbbells with your palms facing in and your arms straight down at your sides at arms'' length. This will be your starting position.","While maintaining the torso stationary (no swinging), lift the dumbbells to your side with a slight bend on the elbow and the hands slightly tilted forward as if pouring water in a glass. Continue to go up until you arms are parallel to the floor. Exhale as you execute this movement and pause for a second at the top.","Lower the dumbbells back down slowly to the starting position as you inhale.","Repeat for the recommended amount of repetitions."]', NULL, '["Seated_Side_Lateral_Raise/0.jpg","Seated_Side_Lateral_Raise/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Seated_Triceps_Press', 'Seated Triceps Press', 'upper arms', 'triceps', '[]', 'dumbbell', 'strength', 'beginner', '["Sit down on a bench with back support and grasp a dumbbell with both hands and hold it overhead at arm''s length. Tip: a better way is to have somebody hand it to you especially if it is very heavy. The resistance should be resting in the palms of your hands with your thumbs around it. The palm of the hand should be facing inward. This will be your starting position.","Keeping your upper arms close to your head (elbows in) and perpendicular to the floor, lower the resistance in a semi-circular motion behind your head until your forearms touch your biceps. Tip: The upper arms should remain stationary and only the forearms should move. Breathe in as you perform this step.","Go back to the starting position by using the triceps to raise the dumbbell. Breathe out as you perform this step.","Repeat for the recommended amount of repetitions."]', NULL, '["Seated_Triceps_Press/0.jpg","Seated_Triceps_Press/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Seated_Two-Arm_Palms-Up_Low-Pulley_Wrist_Curl', 'Seated Two-Arm Palms-Up Low-Pulley Wrist Curl', 'lower arms', 'forearms', '[]', 'cable', 'strength', 'beginner', '["Put a bench in front of a low pulley machine that has a barbell or EZ Curl attachment on it.","Move the bench far enough away so that when you bring the handle to the top of your thighs tension is created on the cable due to the weight stack being moved up.","Now hold the handle with both hands, palms up, using a shoulder-width grip.","Step back and sit on the bench with your feet about shoulder width apart, firmly on the floor.","Lean forward and place the forearms on your thighs with the back of your wrists over your knees. This will be your starting position.","Lower the bar as far as possible, while inhaling and keeping a tight grip.","Now curl the bar up as high as possible while contracting the forearms. Tip: Only the wrist should move; not the forearms.","After a second contraction at the top go back to the starting position as you inhale.","Repeat for the recommended amount of repetitions."]', NULL, '["Seated_Two-Arm_Palms-Up_Low-Pulley_Wrist_Curl/0.jpg","Seated_Two-Arm_Palms-Up_Low-Pulley_Wrist_Curl/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-See-Saw_Press_Alternating_Side_Press', 'See-Saw Press (Alternating Side Press)', 'shoulders', 'shoulders', '["abdominals","triceps"]', 'dumbbell', 'strength', 'intermediate', '["Grab a dumbbell with each hand and stand up erect.","Clean (lift) the dumbbells to the chest/shoulder level and then rotate your wrists so that your palms are facing towards you as if you were getting ready to perform an Arnold Press. This will be your starting position.","Now start extending your left arm overhead as you rotate the wrist so that the palm of your hand faces forward as you go up. Your elbows should come out also as you lift the weight. Simultaneously, you will also be bending from your hip to your opposite side. Tip: If you perform the exercise correctly, is should look as if you are trying to reach for something overhead on the right hand side of your body, but with your left arm. Breathe out as you perform this movement.","Once you reach the top position breathe in. Then, with the weight fully extended overhead and you bent over to your right hand side, begin the movement to the left side.","Repeat for the recommended amount of repetitions."]', NULL, '["See-Saw_Press_Alternating_Side_Press/0.jpg","See-Saw_Press_Alternating_Side_Press/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Shotgun_Row', 'Shotgun Row', 'back', 'lats', '["biceps","middle back"]', 'cable', 'strength', 'beginner', '["Attach a single handle to a low cable.","After selecting the correct weight, stand a couple feet back with a wide-split stance. Your arm should be extended and your shoulder forward. This will be your starting position.","Perform the movement by retracting the shoulder and flexing the elbow. As you pull, supinate the wrist, turning the palm upward as you go.","After a brief pause, return to the starting position."]', NULL, '["Shotgun_Row/0.jpg","Shotgun_Row/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Shoulder_Circles', 'Shoulder Circles', 'shoulders', 'shoulders', '["traps"]', 'body only', 'stretching', 'beginner', '["With shoulders relaxed and arms resting loosely at your sides (or in your lap if you''re seated), gently roll your shoulders forward, up, back, and down.","Reverse direction. You can do this exercise alternating shoulders or both at the same time."]', NULL, '["Shoulder_Circles/0.jpg","Shoulder_Circles/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Shoulder_Raise', 'Shoulder Raise', 'shoulders', 'shoulders', '["lats"]', 'body only', 'stretching', 'beginner', '["Relax your arms to your sides and raise your shoulders up toward your ears, then back down."]', NULL, '["Shoulder_Raise/0.jpg","Shoulder_Raise/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Shoulder_Stretch', 'Shoulder Stretch', 'shoulders', 'shoulders', '[]', 'body only', 'stretching', 'beginner', '["Reach your left arm across your body and hold it straight."]', NULL, '["Shoulder_Stretch/0.jpg","Shoulder_Stretch/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Side-Lying_Floor_Stretch', 'Side-Lying Floor Stretch', 'back', 'lats', '[]', 'body only', 'stretching', 'beginner', '["First lie on your left side, bending your left knee in front of you to stabilize your torso (use your abdominal muscles as well to hold you upright).","Straighten your right leg and rest the right foot on the floor behind your left. Straighten your right arm over your head and gently pull on your right wrist to stretch the entire right side of the body. Switch sides."]', NULL, '["Side-Lying_Floor_Stretch/0.jpg","Side-Lying_Floor_Stretch/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Side_Bridge', 'Side Bridge', 'waist', 'abdominals', '["shoulders"]', 'body only', 'strength', 'beginner', '[]', NULL, '["Side_Bridge/0.jpg","Side_Bridge/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Side_Hop-Sprint', 'Side Hop-Sprint', 'upper legs', 'quadriceps', '["abductors","adductors","calves","hamstrings"]', 'other', 'plyometrics', 'beginner', '["Stand to the side of a cone or hurdle.","Begin this drill by hopping sideways over the obstacle, rebounding out of your landing to hop back to where you started.","Hop for a prescribed number or repetitions as quickly as possible, and finish this drill by sprinting a short distance upon landing the last hop."]', NULL, '["Side_Hop-Sprint/0.jpg","Side_Hop-Sprint/1.jpg"]', 9.8, 'sets', 0, 'fedb', 1),
('fe-Side_Jackknife', 'Side Jackknife', 'waist', 'abdominals', '[]', 'body only', 'strength', 'beginner', '[]', NULL, '["Side_Jackknife/0.jpg","Side_Jackknife/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Side_Lateral_Raise', 'Side Lateral Raise', 'shoulders', 'shoulders', '[]', 'dumbbell', 'strength', 'beginner', '["Pick a couple of dumbbells and stand with a straight torso and the dumbbells by your side at arms length with the palms of the hand facing you. This will be your starting position.","While maintaining the torso in a stationary position (no swinging), lift the dumbbells to your side with a slight bend on the elbow and the hands slightly tilted forward as if pouring water in a glass. Continue to go up until you arms are parallel to the floor. Exhale as you execute this movement and pause for a second at the top.","Lower the dumbbells back down slowly to the starting position as you inhale.","Repeat for the recommended amount of repetitions."]', NULL, '["Side_Lateral_Raise/0.jpg","Side_Lateral_Raise/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Side_Laterals_to_Front_Raise', 'Side Laterals to Front Raise', 'shoulders', 'shoulders', '["traps"]', 'dumbbell', 'strength', 'beginner', '["In a standing position, hold a pair of dumbbells at your side. This will be your starting position.","Keeping your elbows slightly bent, raise the weights directly in front of you to shoulder height, avoiding any swinging or cheating.","At the top of the exercise move the weights out in front of you, keeping your arms extended.","Lower the weights with a controlled motion.","On the next repetition, raise the weights in front of you to shoulder height before moving the weights laterally to your sides.","Lower the weights to the starting position."]', NULL, '["Side_Laterals_to_Front_Raise/0.jpg","Side_Laterals_to_Front_Raise/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Side_Leg_Raises', 'Side Leg Raises', 'upper legs', 'adductors', '[]', 'body only', 'stretching', 'beginner', '["Stand next to a chair, which you may hold onto as a support. Stand on one leg. This will be your starting position.","Keeping your leg straight, raise it as far out to the side as possible, and swing it back down, allowing it to cross the opposite leg.","Repeat this swinging motion 5-10 times, increasing the range of motion as you do so."]', NULL, '["Side_Leg_Raises/0.jpg","Side_Leg_Raises/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Side_Lying_Groin_Stretch', 'Side Lying Groin Stretch', 'upper legs', 'adductors', '["hamstrings"]', 'body only', 'stretching', 'beginner', '["Start off by lying on your right side and bend your right knee in front of you to stabilize the torso.","Rest your head on your right hand or shoulder. Lift your left leg upward and hold it by the back of the knee (easier) or the foot (harder).","Pull your left knee in toward your left shoulder and simultaneously press your foot or knee down to the floor. To intensify this stretch, straighten your left leg. Switch sides."]', NULL, '["Side_Lying_Groin_Stretch/0.jpg","Side_Lying_Groin_Stretch/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Side_Neck_Stretch', 'Side Neck Stretch', 'neck', 'neck', '[]', 'body only', 'stretching', 'beginner', '["Start with your shoulders relaxed, gently tilt your head towards your shoulder.","Assist stretch with a gentle pull on the side of the head."]', NULL, '["Side_Neck_Stretch/0.jpg","Side_Neck_Stretch/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Side_Standing_Long_Jump', 'Side Standing Long Jump', 'upper legs', 'quadriceps', '["calves","glutes","hamstrings"]', 'body only', 'plyometrics', 'beginner', '["Begin standing with your feet hip width apart in an athletic stance. Your head and chest should be up, knees and hips slightly bent. This will be your starting position.","Leaning to your right, extend through your hips, knees, and ankles to jump into the air. Block with the arms to lead the movement, jumping as far to your right as you can.","Land facing the same direction with your feet hip width apart, absorbing the impact through your lower body."]', NULL, '["Side_Standing_Long_Jump/0.jpg","Side_Standing_Long_Jump/1.jpg"]', 8, 'sets', 0, 'fedb', 1),
('fe-Side_To_Side_Chins', 'Side To Side Chins', 'back', 'lats', '["biceps","forearms","middle back","shoulders"]', 'other', 'strength', 'intermediate', '["Grab the pull-up bar with the palms facing forward using a wide grip.","As you have both arms extended in front of you holding the bar at a wide grip, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.","Pull your torso up while leaning to the left hand side until the bar almost touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of the movement. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space (no swinging) and only the arms should move. The forearms should do no other work other than hold the bar.","After a second of contraction, inhale as you go back to the starting position.","Now, pull your torso up while leaning to the right hand side until the bar almost touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of the movement. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.","After a second of contraction, inhale as you go back to the starting position.","Repeat steps 3-6 until you have performed the prescribed amount of repetitions for each side."]', NULL, '["Side_To_Side_Chins/0.jpg","Side_To_Side_Chins/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Side_Wrist_Pull', 'Side Wrist Pull', 'shoulders', 'shoulders', '["forearms","lats"]', 'body only', 'stretching', 'beginner', '["This stretch works best standing. Cross your left arm over the midline of your body and hold the left wrist in your right hand down at the level of your hips. Start the stretch with a bent left arm.","Slowly straighten, pull, and lift it up to shoulder height, as pictured. Feel this stretch originate in your back, not your shoulders, and don''t pull too hard on the shoulders joint. Switch sides."]', NULL, '["Side_Wrist_Pull/0.jpg","Side_Wrist_Pull/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Side_to_Side_Box_Shuffle', 'Side to Side Box Shuffle', 'upper legs', 'quadriceps', '["abductors","adductors","calves","hamstrings"]', 'other', 'plyometrics', 'beginner', '["Stand to one side of the box with your left foot resting on the middle of it.","To begin, jump up and over to the other side of the box, landing with your right foot on top of the box and your left foot on the floor. Swing your arms to aid your movement.","Continue shuffling back and forth across the box."]', NULL, '["Side_to_Side_Box_Shuffle/0.jpg","Side_to_Side_Box_Shuffle/1.jpg"]', 8, 'sets', 0, 'fedb', 1),
('fe-Single-Arm_Cable_Crossover', 'Single-Arm Cable Crossover', 'chest', 'chest', '[]', 'cable', 'strength', 'beginner', '["Begin by moving the pulleys to the high position, select the resistance to be used, and take a handle in each hand.","Step forward in front of both pulleys with your arms extended in front of you, bringing your hands together. Your head and chest should be up as you lean forward, while your feet should be staggered. This will be your starting position.","Keeping your left arm in place, allow your right arm to extend out to the side, maintaining a slight bend at the elbow. The right arm should be perpendicular to the body at approximately shoulder level.","Return your arm back to the starting position by pulling your hand back to the midline of the body.","Hold for a second at the starting position and repeat the movement on the opposite side. Continue alternating back and forth for the prescribed number of repetitions."]', NULL, '["Single-Arm_Cable_Crossover/0.jpg","Single-Arm_Cable_Crossover/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Single-Arm_Linear_Jammer', 'Single-Arm Linear Jammer', 'shoulders', 'shoulders', '["chest","triceps"]', 'barbell', 'strength', 'intermediate', '["Position a bar into a landmine or securely anchor it in a corner. Load the bar to an appropriate weight.","Raise the bar from the floor, taking it to your shoulders with one or both hands. Adopt a wide stance. This will be your starting position.","Perform the movement by extending the elbow, pressing the weight up. Move explosively, extending the hips and knees fully to produce maximal force.","Return to the starting position."]', NULL, '["Single-Arm_Linear_Jammer/0.jpg","Single-Arm_Linear_Jammer/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Single-Cone_Sprint_Drill', 'Single-Cone Sprint Drill', 'upper legs', 'quadriceps', '["calves","glutes","hamstrings"]', 'other', 'plyometrics', 'beginner', '["This drill teaches quick foot action. You need a single cone. Begin standing next to the cone with one arm back and one arm forward.","Chop the feet as quickly as possible, blocking with the arms. Circle the cone, keep your knees up, with violent foot action.","Rest after three trips around the cone."]', NULL, '["Single-Cone_Sprint_Drill/0.jpg","Single-Cone_Sprint_Drill/1.jpg"]', 9.8, 'sets', 0, 'fedb', 1),
('fe-Single-Leg_High_Box_Squat', 'Single-Leg High Box Squat', 'upper legs', 'quadriceps', '["glutes","hamstrings"]', 'other', 'strength', 'beginner', '["Position a box in a rack. Secure a band or rope in place above the box.","Standing in front of it, step onto the box to a full standing position, letting your other leg remain unsupported. Hold onto the band for balance",". Continue stepping up and down on the same leg before switching to the opposite side."]', NULL, '["Single-Leg_High_Box_Squat/0.jpg","Single-Leg_High_Box_Squat/1.jpg"]', 5, 'sets', 0, 'fedb', 1)
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('fe-Single-Leg_Hop_Progression', 'Single-Leg Hop Progression', 'upper legs', 'quadriceps', '["abductors","adductors","calves","hamstrings"]', 'other', 'plyometrics', 'beginner', '["Arrange a line of cones in front of you. Assume a relaxed standing position, balanced on one leg. Raise the knee of your opposite leg. This will be your starting position.","Hop forward, jumping and landing with the same leg over the cone.","Use a countermovement jump to hop from cone to cone.","At the end, turn around and go back on the other leg."]', NULL, '["Single-Leg_Hop_Progression/0.jpg","Single-Leg_Hop_Progression/1.jpg"]', 8, 'sets', 0, 'fedb', 1),
('fe-Single-Leg_Lateral_Hop', 'Single-Leg Lateral Hop', 'upper legs', 'quadriceps', '["abductors","adductors","calves","hamstrings"]', 'other', 'plyometrics', 'beginner', '["Stand to the side of a cone or hurdle. To get into the start position, stand on one leg with your knee slightly bent.","To begin, execute a counterjump to hop sideways over the cone.","Land on your jumping leg, and immediately rebound out of it by jumping back to the start position.","Continue hopping back and forth."]', NULL, '["Single-Leg_Lateral_Hop/0.jpg","Single-Leg_Lateral_Hop/1.jpg"]', 8, 'sets', 0, 'fedb', 1),
('fe-Single-Leg_Leg_Extension', 'Single-Leg Leg Extension', 'upper legs', 'quadriceps', '[]', 'machine', 'strength', 'beginner', '["Seat yourself in the machine and adjust it so that you are positioned properly. The pad should be against the lower part of the shin but not in contact with the ankle. Adjust the seat so that the pivot point is in line with your knee. Select a weight appropriate for your abilities.","Maintaining good posture, fully extend one leg, pausing at the top of the motion.","Return to the starting position without letting the weight stop, keeping tension on the muscle.","Repeat for the desired number of repetitions."]', NULL, '["Single-Leg_Leg_Extension/0.jpg","Single-Leg_Leg_Extension/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Single-Leg_Stride_Jump', 'Single-Leg Stride Jump', 'upper legs', 'quadriceps', '["abductors","adductors","calves","hamstrings"]', 'other', 'plyometrics', 'beginner', '["Stand to the side of a box with your inside foot on top of it, close to the edge.","Begin by swinging the arms upward as you push through the top leg, jumping upward as high as possible. Attempt to drive the opposite knee upward.","Land in the same position that you started, using your inside leg to decelerate the impact."]', NULL, '["Single-Leg_Stride_Jump/0.jpg","Single-Leg_Stride_Jump/1.jpg"]', 8, 'sets', 0, 'fedb', 1),
('fe-Single_Dumbbell_Raise', 'Single Dumbbell Raise', 'shoulders', 'shoulders', '["forearms","traps"]', 'dumbbell', 'strength', 'beginner', '["With a wide stance, hold a dumbell with both hands, grasping the head of the dumbbell instead of the handle. Your arms should be extended and hanging at the waist. This will be your starting position.","Raise the weight until it is above shoulder level, keeping your arms extended. Your torso and hips should remain stationary throughout the movement.","Return to the starting position and repeat for the recommended amount of repetitions."]', NULL, '["Single_Dumbbell_Raise/0.jpg","Single_Dumbbell_Raise/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Single_Leg_Butt_Kick', 'Single Leg Butt Kick', 'upper legs', 'quadriceps', '["calves","hamstrings"]', 'body only', 'plyometrics', 'beginner', '["Begin by standing on one leg, with the bent knee raised. This will be your start position.","Using a countermovement jump, take off upward by extending the hip, knee, and ankle of the grounded leg.","Immediately flex the knee and attempt to touch your butt with the heel of your jumping leg.","Return the leg to a partially bent position underneath the hips and land. Your opposite leg should stay in relatively the same position throughout the drill."]', NULL, '["Single_Leg_Butt_Kick/0.jpg","Single_Leg_Butt_Kick/1.jpg"]', 8, 'sets', 0, 'fedb', 1),
('fe-Single_Leg_Glute_Bridge', 'Single Leg Glute Bridge', 'upper legs', 'glutes', '["hamstrings"]', 'body only', 'strength', 'beginner', '["Lay on the floor with your feet flat and knees bent.","Raise one leg off of the ground, pulling the knee to your chest. This will be your starting position.","Execute the movement by driving through the heel, extending your hip upward and raising your glutes off of the ground.","Extend as far as possible, pause and then return to the starting position."]', NULL, '["Single_Leg_Glute_Bridge/0.jpg","Single_Leg_Glute_Bridge/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Single_Leg_Push-off', 'Single Leg Push-off', 'upper legs', 'quadriceps', '["calves","hamstrings"]', 'other', 'plyometrics', 'beginner', '["Stand on the ground with one foot resting on the box, heel close to the edge.","Push off with your foot on top of the box, trying to gain as much height as possible by extending through the hip and knee.","Land with the same foot on top of the box, returning your other foot back to the start position."]', NULL, '["Single_Leg_Push-off/0.jpg","Single_Leg_Push-off/1.jpg"]', 8, 'sets', 0, 'fedb', 1),
('fe-Sit-Up', 'Sit-Up', 'waist', 'abdominals', '[]', 'body only', 'strength', 'beginner', '["Lie down on the floor placing your feet either under something that will not move or by having a partner hold them. Your legs should be bent at the knees.","Place your hands behind your head and lock them together by clasping your fingers. This is the starting position.","Elevate your upper body so that it creates an imaginary V-shape with your thighs. Breathe out when performing this part of the exercise.","Once you feel the contraction for a second, lower your upper body back down to the starting position while inhaling.","Repeat for the recommended amount of repetitions."]', NULL, '["Sit-Up/0.jpg","Sit-Up/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Sit_Squats', 'Sit Squats', 'upper legs', 'quadriceps', '["abductors","glutes","hamstrings"]', 'body only', 'stretching', 'beginner', '["Stand with your feet shoulder width apart. This will be your starting position.","Begin the movement by flexing your knees and hips, sitting back with your hips.","Continue until you have squatted a portion of the way down, but are above parallel, and quickly reverse the motion until you return to the starting position. Repeat for 5-10 repetitions."]', NULL, '["Sit_Squats/0.jpg","Sit_Squats/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Skating', 'Skating', 'cardio', 'quadriceps', '["abductors","adductors","calves","glutes","hamstrings"]', 'other', 'cardio', 'intermediate', '["Roller skating is a fun activity which can be effective in improving cardiorespiratory fitness and muscular endurance. It requires relatively good balance and coordination. It is necessary to learn the basics of skating including turning and stopping and to wear protective gear to avoid possible injury.","You can skate at a comfortable pace for 30 minutes straight. If you want a cardio challenge, do interval skating — speed skate two minutes of every five minutes, using the remaining three minutes to recover. A 150 lb person will typically burn about 175 calories in 30 minutes skating at a comfortable pace, similar to brisk walking."]', NULL, '["Skating/0.jpg","Skating/1.jpg"]', 7, 'time', 0, 'fedb', 1),
('fe-Sled_Drag_-_Harness', 'Sled Drag - Harness', 'upper legs', 'quadriceps', '["calves","glutes","hamstrings"]', 'other', 'strongman', 'beginner', '["To begin, load the sled with the desired weight and attach the pulling strap. You can pull with handles, use a harness, or attach the pulling strap to a weight belt.","Whether pulling forwards or backwards, lean in the direction of travel and progress by extending through the hips and knees."]', NULL, '["Sled_Drag_-_Harness/0.jpg","Sled_Drag_-_Harness/1.jpg"]', 7, 'sets', 0, 'fedb', 1),
('fe-Sled_Overhead_Backward_Walk', 'Sled Overhead Backward Walk', 'shoulders', 'shoulders', '["calves","middle back","quadriceps"]', 'other', 'strength', 'beginner', '["Attach dual handles to a sled connected by a rope or chain. Load the sled to a light weight.","Face the sled, backing up until there is some tension in the line. Hold your hands directly above your head with your elbows extended. This will be your starting position.","Walk backwards, keeping your arms raised above your head. Avoid jerky movements."]', NULL, '["Sled_Overhead_Backward_Walk/0.jpg","Sled_Overhead_Backward_Walk/1.jpg"]', 3.5, 'sets', 0, 'fedb', 1),
('fe-Sled_Overhead_Triceps_Extension', 'Sled Overhead Triceps Extension', 'upper arms', 'triceps', '[]', 'other', 'strength', 'beginner', '["Attach dual handles to a sled using a chain or rope. Load the sled to an appropriate load.","Facing away from the sled, step away until there is tension in the line. Raise your hands above your head, keeping them together, palms facing each other. Your elbows should be pointed upward with the elbows flexed. This will be your starting position.","Extend through the elbow to straighten the arm. Ensure that your upper arm stays in position to isolate the triceps.","Upon full extension, step forward to take the slack out of the line. You may keep your feet staggered for more stability."]', NULL, '["Sled_Overhead_Triceps_Extension/0.jpg","Sled_Overhead_Triceps_Extension/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Sled_Push', 'Sled Push', 'upper legs', 'quadriceps', '["calves","chest","glutes","hamstrings","triceps"]', 'other', 'strongman', 'beginner', '["Load your pushing sled with the desired weight.","Take an athletic posture, leaning into the sled with your arms fully extended, grasping the handles. Push the sled as fast as possible, focusing on extending your hips and knees to strengthen your posterior chain."]', NULL, '["Sled_Push/0.jpg","Sled_Push/1.jpg"]', 7, 'sets', 0, 'fedb', 1),
('fe-Sled_Reverse_Flye', 'Sled Reverse Flye', 'shoulders', 'shoulders', '[]', 'other', 'strength', 'beginner', '["Attach dual handles to a sled connected by a rope or chain. Load the sled to a light weight.","Face the sled, backing up until there is some tension in the line. Take both handles at arms length at about waist level. Bend the knees slightly and keep your chest and head up. This will be your starting position.","Without flexing the elbow, pull the handles upward and apart, performing a reverse fly with some external rotation. Your palms should be facing forward as you do this.","Return to the starting position, taking a couple steps back to take the slack out of the line."]', NULL, '["Sled_Reverse_Flye/0.jpg","Sled_Reverse_Flye/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Sled_Row', 'Sled Row', 'back', 'middle back', '["biceps","lats"]', 'other', 'strength', 'beginner', '["Attach dual handles to a sled connected by a rope or chain. Load the sled to an appropriate weight. Face the sled, backing up until there is some tension in the line.","With a handle in each hand, bend the knees slightly, keep your head and chest up, and begin with your arms extended.","To initiate the movement, flex the elbow as you retract your shoulder blades, pulling the sled towards you.","Take a step or two back to get tension in the line and repeat."]', NULL, '["Sled_Row/0.jpg","Sled_Row/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Sledgehammer_Swings', 'Sledgehammer Swings', 'waist', 'abdominals', '["calves","forearms","lats","middle back","shoulders"]', 'other', 'plyometrics', 'beginner', '["You will need a tire and a sledgehammer for this exercise. Stand in front of the tire about two feet away from it with a staggered stance. Grip the sledgehammer.","If you are right handed, your left hand should be at the bottom of the handle, and your right hand should be choking up closer to the head.","As you bring the sledge up, your right hand slides toward the head; as you swing down, your right hand will slide down to join your left hand. Slam it down as hard as you can against the tire. Control the bounce of the hammer off of the tire.","Repeat on the other side."]', NULL, '["Sledgehammer_Swings/0.jpg","Sledgehammer_Swings/1.jpg"]', 8, 'sets', 0, 'fedb', 1),
('fe-Smith_Incline_Shoulder_Raise', 'Smith Incline Shoulder Raise', 'shoulders', 'shoulders', '["chest"]', 'barbell', 'strength', 'beginner', '["Place an incline bench underneath the smith machine. Place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Once the weight you need is selected, lie down on the incline bench and make sure your shoulders are aligned right under the barbell.","Using a shoulder width pronated (palms forward) grip, lift the bar from the rack and hold it straight over you with a slight bend at the elbows. This will be your starting position.","As you breathe out, lift the bar up until your arms are fully extended. Note: The contraction should be felt around the shoulders.","After a second pause, bring the bar back down to the starting position as you breathe in.","Repeat the movement for the prescribed amount of repetitions.","When you are done, place the bar back in the rack."]', NULL, '["Smith_Incline_Shoulder_Raise/0.jpg","Smith_Incline_Shoulder_Raise/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Smith_Machine_Behind_the_Back_Shrug', 'Smith Machine Behind the Back Shrug', 'back', 'traps', '["shoulders"]', 'machine', 'strength', 'beginner', '["With the bar at thigh level, load an appropriate weight.","Stand with the bar behind you, taking a shoulder-width, pronated grip on the bar and unhook the weight. You should be standing up straight with your head and chest up and your arms extended. This will be your starting position.","Initiate the movement by shrugging your shoulders straight up. Do not flex the arms or wrist during the movement.","After a brief pause return the weight to the starting position.","Repeat for the desired number of repetitions before engaging the hooks to rack the weight."]', NULL, '["Smith_Machine_Behind_the_Back_Shrug/0.jpg","Smith_Machine_Behind_the_Back_Shrug/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Smith_Machine_Bench_Press', 'Smith Machine Bench Press', 'chest', 'chest', '["shoulders","triceps"]', 'machine', 'strength', 'beginner', '["Place a flat bench underneath the smith machine. Now place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Once the weight you need is selected, lie down on the flat bench. Using a pronated grip that is wider than shoulder width, unlock the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.","As you breathe in, come down slowly until you feel the bar on your middle chest.","After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.","Repeat the movement for the prescribed amount of repetitions.","When you are done, lock the bar back in the rack."]', NULL, '["Smith_Machine_Bench_Press/0.jpg","Smith_Machine_Bench_Press/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Smith_Machine_Bent_Over_Row', 'Smith Machine Bent Over Row', 'back', 'middle back', '["biceps","lats","shoulders"]', 'machine', 'strength', 'beginner', '["Set the barbell attached to the smith machine to a height that is about 2 inches below your knees.","Bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up.","Now grasp the barbell using an overhand (pronated) grip and unlock it from the smith machine rack. Then let it hang directly in front of you as your arms hang extended perpendicular to the floor and your torso. This is your starting position.","While keeping the torso stationary, lift the barbell as you breathe out, keeping the elbows close to the body and not doing any force with the forearm other than holding the weights. On the top contracted position, squeeze the back muscles and hold for a second.","Slowly lower the weight again to the starting position as you inhale.","Repeat for the recommended amount of repetitions."]', NULL, '["Smith_Machine_Bent_Over_Row/0.jpg","Smith_Machine_Bent_Over_Row/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Smith_Machine_Calf_Raise', 'Smith Machine Calf Raise', 'lower legs', 'calves', '[]', 'machine', 'strength', 'beginner', '["Place a block or weight plate below the bar on the Smith machine. Set the bar to a position that best matches your height. Once the correct height is chosen and the bar is loaded, step onto the plates with the balls of your feet and place the bar on the back of your shoulders.","Take the bar with both hands facing forward. Rotate the bar to unrack it. This will be your starting position.","Raise your heels as high as possible by pushing off of the balls of your feet, flexing your calf at the top of the contraction. Your knees should remain extended. Hold the contracted position for a second before you start to go back down.","Return slowly to the starting position as you breathe in while lowering your heels.","Repeat for the recommended amount of repetitions."]', NULL, '["Smith_Machine_Calf_Raise/0.jpg","Smith_Machine_Calf_Raise/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Smith_Machine_Close-Grip_Bench_Press', 'Smith Machine Close-Grip Bench Press', 'upper arms', 'triceps', '["chest","shoulders"]', 'machine', 'strength', 'beginner', '["Place a flat bench underneath the smith machine. Place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Once the weight you need is selected, lie down on the flat bench. Using a close and pronated grip (palms facing forward) that is around shoulder width, unlock the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.","As you breathe in, come down slowly until you feel the bar on your middle chest. Tip: Make sure that as opposed to a regular bench press, you keep the elbows close to the torso at all times in order to maximize triceps involvement.","After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your triceps muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.","Repeat the movement for the prescribed amount of repetitions.","When you are done, lock the bar back in the rack."]', NULL, '["Smith_Machine_Close-Grip_Bench_Press/0.jpg","Smith_Machine_Close-Grip_Bench_Press/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Smith_Machine_Decline_Press', 'Smith Machine Decline Press', 'chest', 'chest', '["shoulders","triceps"]', 'machine', 'strength', 'beginner', '["Position a decline bench in the rack so that the bar will be above your chest. Load an appropriate weight and take your place on the bench.","Rotate the bar to unhook it from the rack and fully extend your arms. Your back should be slightly arched and your shoulder blades retracted. This will be your starting position.","Begin the movement by flexing your arms, lowering the bar to your chest.","Pause briefly, and then extend your arms to push the weight back to the starting position.","After completing the desired number of repetitions, rotate the bar to rack the weight."]', NULL, '["Smith_Machine_Decline_Press/0.jpg","Smith_Machine_Decline_Press/1.jpg"]', 5, 'sets', 0, 'fedb', 1)
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('fe-Smith_Machine_Hang_Power_Clean', 'Smith Machine Hang Power Clean', 'upper legs', 'hamstrings', '["glutes","lower back","quadriceps","shoulders","traps"]', 'machine', 'strength', 'intermediate', '["Position the bar at knee height and load it to an appropriate weight.","Take a pronated grip on the bar outside of shoulder width and unhook the bar from the machine. Your arms should be fully extended with your head and chest up. Your elbows should be pointed out with your shoulders back and down. Your hips should be back, loading the tension into the hamstrings. This will be your starting position.","Initate the movement by forcefully extending the hips and knees, accelerating into the bar. Ensure that you keep your arms straight during this part of the motion.","Upon full extension, rebend the hips and knees to lower your receiving position.","Allow the arms to flex at this point, rotating the elbows around the bar to receive it on your shoulders.","Extend through the hips and knees to come to a standing position with the bar racked on your shoulders to complete the movement."]', NULL, '["Smith_Machine_Hang_Power_Clean/0.jpg","Smith_Machine_Hang_Power_Clean/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Smith_Machine_Hip_Raise', 'Smith Machine Hip Raise', 'waist', 'abdominals', '[]', 'machine', 'strength', 'beginner', '["Position a bench in the rack and load the bar to an appropriate weight. Lie down on the bench, placing the bottom of your feet against the bar. Unlock the bar and extend your legs. You may need to use your hands to assist you. For added stability grasp the sides of the Smith Machine. This will be your starting position.","Initiate the movement by rotating your pelvis, flexing your spine to raise your hips off of the bench. Maintain a slight bend in the knees throughout the motion.","After a brief pause, return the hips to the bench.","Repeat for the desired number of repetitions."]', NULL, '["Smith_Machine_Hip_Raise/0.jpg","Smith_Machine_Hip_Raise/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Smith_Machine_Incline_Bench_Press', 'Smith Machine Incline Bench Press', 'chest', 'chest', '["shoulders","triceps"]', 'machine', 'strength', 'beginner', '["Place an incline bench underneath the smith machine. Place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Once the weight you need is selected, lie down on the incline bench and make sure your upper chest is aligned with the barbell. Using a pronated grip (palms facing forward) that is wider than shoulder width, unlock the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.","As you breathe in, come down slowly until you feel the bar on your upper chest.","After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.","Repeat the movement for the prescribed amount of repetitions.","When you are done, place the bar back in the rack."]', NULL, '["Smith_Machine_Incline_Bench_Press/0.jpg","Smith_Machine_Incline_Bench_Press/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Smith_Machine_Leg_Press', 'Smith Machine Leg Press', 'upper legs', 'quadriceps', '["calves","glutes","hamstrings"]', 'machine', 'strength', 'intermediate', '["Position a Smith machine bar a couple feet off of the ground. Ensure that it is resting on the safeties. After loading the bar to an appropriate weight, lie underneath the bar. Place the middle of your feet on the bar, tucking your knees to your chest. This will be your starting position.","Begin the movement by driving through your feet to move the bar upward, extending the hips and knees. Do not lock out your knees.","At the top of the motion, pause briefly before returning to the starting position."]', NULL, '["Smith_Machine_Leg_Press/0.jpg","Smith_Machine_Leg_Press/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Smith_Machine_One-Arm_Upright_Row', 'Smith Machine One-Arm Upright Row', 'shoulders', 'shoulders', '["biceps","traps"]', 'machine', 'strength', 'beginner', '["With the bar at thigh level, load an appropriate weight.","Take a wide grip on the bar and unhook the weight, removing your off hand from the bar. Your arm should be extended as you stand up straight with your head and chest up. This will be your starting position.","Begin the movement by flexing the elbow, raising the upper arm with the elbow pointed out. Continue until your upper arm is parallel to the floor.","After a brief pause, return the weight to the starting position.","Repeat for the desired number of repetitions before engaging the hooks to rack the weight."]', NULL, '["Smith_Machine_One-Arm_Upright_Row/0.jpg","Smith_Machine_One-Arm_Upright_Row/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Smith_Machine_Overhead_Shoulder_Press', 'Smith Machine Overhead Shoulder Press', 'shoulders', 'shoulders', '["triceps"]', 'machine', 'strength', 'beginner', '["To begin, place a flat bench (or preferably one with back support) underneath a smith machine. Position the barbell at a height so that when seated on the flat bench, the arms must be almost fully extended to reach the barbell.","Once you have the correct height, sit slightly in behind the barbell so that there is an imaginary straight line from the tip of your nose to the barbell. Your feet should be stationary. Grab the barbell with the palms facing forward, unlock it and lift it up so that your arms are fully extended. This is the starting position.","Slowly begin to lower the barbell until it is level with your chin while inhaling.","Then lift the barbell back to the starting position using your shoulders while exhaling.","Repeat for the recommended amount of repetitions."]', NULL, '["Smith_Machine_Overhead_Shoulder_Press/0.jpg","Smith_Machine_Overhead_Shoulder_Press/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Smith_Machine_Pistol_Squat', 'Smith Machine Pistol Squat', 'upper legs', 'quadriceps', '["calves","glutes","hamstrings"]', 'machine', 'strength', 'intermediate', '["To begin, first set the bar to a position that best matches your height. Step under it and position the bar across the back of your shoulders.","Take the bar with your hands facing forward, unlock it and lift it off the rack by extending your legs. 3","Move one foot forward about 12 inches in front of the bar. Extend the other leg out in front of you, holding it off the ground. Look forward at all times and maintain a neutral or slightly arched spine. This will be your starting position.","Maintaining good posture, lower yourself by flexing the knee and hip, going down as far as flexibility allows.","Pause briefly at the bottom and then return to the starting position by driving through the heel of your foot, extending the knee and hip."]', NULL, '["Smith_Machine_Pistol_Squat/0.jpg","Smith_Machine_Pistol_Squat/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Smith_Machine_Reverse_Calf_Raises', 'Smith Machine Reverse Calf Raises', 'lower legs', 'calves', '[]', 'machine', 'strength', 'beginner', '["Adjust the barbell on the smith machine to fit your height and align a raised platform right under the bar.","Stand on the platform with the heels of your feet secured on top of it with the balls of your feet extending off it. Position your toes facing forward with a shoulder width stance.","Now, place your shoulders under the barbell while maintaining the foot positioning described and push the barbell up by extending your hips and knees until your torso is standing erect. The knees should be kept with a slight bend; never locked. This will be your starting position. Tip: The barbell on your back is only for balance purposes.","Raise the balls of your feet as you breathe out by extending your toes as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position for a second before you start to go back down.","Slowly go back down to the starting position as you breathe in by lowering the balls of your feet and toes.","Repeat for the recommended amount of repetitions."]', NULL, '["Smith_Machine_Reverse_Calf_Raises/0.jpg","Smith_Machine_Reverse_Calf_Raises/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Smith_Machine_Squat', 'Smith Machine Squat', 'upper legs', 'quadriceps', '["calves","glutes","hamstrings","lower back"]', 'machine', 'strength', 'beginner', '["To begin, first set the bar on the height that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.","Hold on to the bar using both arms at each side (palms facing forward), unlock it and lift it off the rack by first pushing with your legs and at the same time straightening your torso.","Position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance which targets overall development; however you can choose any of the three stances discussed in the foot stances section).","Begin to slowly lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.","Begin to raise the bar as you exhale by pushing the floor with the heel of your foot as you straighten the legs again and go back to the starting position.","Repeat for the recommended amount of repetitions."]', NULL, '["Smith_Machine_Squat/0.jpg","Smith_Machine_Squat/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Smith_Machine_Stiff-Legged_Deadlift', 'Smith Machine Stiff-Legged Deadlift', 'upper legs', 'hamstrings', '["glutes","lower back"]', 'machine', 'strength', 'beginner', '["To begin, set the bar on the smith machine to a height that is around the middle of your thighs. Once the correct height is chosen and the bar is loaded, grasp the bar using a pronated (palms forward) grip that is shoulder width apart. You may need some wrist wraps if using a significant amount of weight.","Lift the bar up by fully extending your arms while keeping your back straight. Stand with your torso straight and your legs spaced using a shoulder width or narrower stance. The knees should be slightly bent. This is your starting position.","Keeping the knees stationary, lower the barbell to over the top of your feet by bending at the waist while keeping your back straight. Keep moving forward as if you were going to pick something from the floor until you feel a stretch on the hamstrings. Exhale as you perform this movement","Start bringing your torso up straight again as soon as you feel the hamstrings stretch by extending your hips and waist until you are back at the starting position. Inhale as you perform this movement.","Repeat for the recommended amount of repetitions."]', NULL, '["Smith_Machine_Stiff-Legged_Deadlift/0.jpg","Smith_Machine_Stiff-Legged_Deadlift/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Smith_Machine_Upright_Row', 'Smith Machine Upright Row', 'back', 'traps', '["biceps","middle back","shoulders"]', 'machine', 'strength', 'beginner', '["To begin, set the bar on the smith machine to a height that is around the middle of your thighs. Once the correct height is chosen and the bar is loaded, grasp the bar using a pronated (palms forward) grip that is shoulder width apart. You may need some wrist wraps if using a significant amount of weight.","Lift the barbell up and fully extend your arms with your back straight. There should be a slight bend at the elbows. This is the starting position.","Use your side shoulders to lift the bar as you exhale. The bar should be close to the body as you move it up. Continue to lift it until it nearly touches your chin. Tip: Your elbows should drive the motion. As you lift the bar, your elbows should always be higher than your forearms. Also, keep your torso stationary and pause for a second at the top of the movement.","Lower the bar back down slowly to the starting position. Inhale as you perform this portion of the movement.","Repeat for the recommended amount of repetitions."]', NULL, '["Smith_Machine_Upright_Row/0.jpg","Smith_Machine_Upright_Row/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Snatch', 'Snatch', 'upper legs', 'quadriceps', '["biceps","glutes","hamstrings","lower back","shoulders","traps","triceps"]', 'barbell', 'olympic weightlifting', 'intermediate', '["Place your feet at a shoulder width stance with the barbell resting right above the connection between the toes and the rest of the foot.","With a palms facing down grip, bend at the knees and keeping the back flat grab the bar using a wider than shoulder width grip. Bring the hips down and make sure that your body drops as if you were going to sit on a chair. This will be your starting position.","Start pushing the floor as if it were a moving platform with your feet and simultaneously start lifting the barbell keeping it close to your legs.","As the bar reaches the middle of your thighs, push the floor with your legs and lift your body to a complete extension in an explosive motion.","Lift your shoulders back in a shrugging movement as you bring the bar up while lifting your elbows out to the side and keeping them above the bar for as long as possible.","Now in a very quick but powerful motion, you have to get your body under the barbell when it has reached a high enough point where it can be controlled and drop while locking your arms and holding the barbell overhead as you assume a squat position.","Finalize the movement by rising up out of the squat position to finish the lift. At the end of the lift both feet should be on line and the arms fully extended holding the barbell overhead."]', NULL, '["Snatch/0.jpg","Snatch/1.jpg"]', 6, 'sets', 0, 'fedb', 1),
('fe-Snatch_Balance', 'Snatch Balance', 'upper legs', 'quadriceps', '["calves","glutes","hamstrings","shoulders","triceps"]', 'barbell', 'olympic weightlifting', 'intermediate', '["Begin with the feet in the pulling position, the bar racked across the back of the shoulders, and the hands placed in a wide snatch grip.","Pop the bar with an abrupt dip and drive of the knees, and aggressively drive under the bar, transitioning the feet into the receiving position.","Receive the bar locked out overhead near the bottom of the squat. The torso should remain vertical, lowering the hips between the legs.","Continue to descend to full depth, and return to a standing position. Carefully lower the weight."]', NULL, '["Snatch_Balance/0.jpg","Snatch_Balance/1.jpg"]', 6, 'sets', 0, 'fedb', 1),
('fe-Snatch_Deadlift', 'Snatch Deadlift', 'upper legs', 'hamstrings', '["forearms","glutes","hamstrings","lower back","quadriceps","traps"]', 'barbell', 'olympic weightlifting', 'intermediate', '["The snatch deadlift strengthens the first pull of the snatch. Begin with a wide snatch grip with the barbell placed on the platform. The feet should be directly under the hips, with the feet turned out. Squat down to the bar, keeping the back in absolute extension with the head facing forward.","Initiate the movement by driving through the heels, raising the hips. The back angle should remain the same until the bar passes the knees.","At that point, drive your hips through the bar as you lay back. Return the bar to the platform by reversing the motion."]', NULL, '["Snatch_Deadlift/0.jpg","Snatch_Deadlift/1.jpg"]', 6, 'sets', 0, 'fedb', 1),
('fe-Snatch_Shrug', 'Snatch Shrug', 'back', 'traps', '["forearms","shoulders"]', 'barbell', 'olympic weightlifting', 'intermediate', '["Begin with a wide grip, with the bar hanging at the mid thigh position. You can use a hook or overhand grip. Your back should be straight and inclined slightly forward.","Shrug your shoulders towards your ears. While this exercise can usually by loaded with heavier weight than a snatch, avoid overloading to the point that the execution slows down."]', NULL, '["Snatch_Shrug/0.jpg","Snatch_Shrug/1.jpg"]', 6, 'sets', 0, 'fedb', 1),
('fe-Snatch_from_Blocks', 'Snatch from Blocks', 'upper legs', 'quadriceps', '["calves","forearms","glutes","hamstrings","lower back","shoulders","traps","triceps"]', 'barbell', 'olympic weightlifting', 'expert', '["Begin with a loaded barbell on boxes or stands of the desired height. A wide grip should be taken on the bar. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the chest up and the head looking forward. The shoulders should be just in front of the bar, with the elbows pointed out. This will be the starting position.","Begin the first pull by driving through the front of the heels, raising the bar from the boxes.","Transition into the second pull by extending through the hips knees and ankles, driving the bar up as quickly as possible. The bar should be close to the body. At peak extension, shrug the shoulders and allow the elbows to flex to the side.","As you move your feet into the receiving position, forcefully pull yourself below the bar as you elevate the bar overhead. The feet should move to just outside the hips, turned out as necessary. Receive the bar with your body as low as possible and the arms fully extended overhead.","Keeping the bar aligned over the front of the heels, your head and chest up, drive through heels of the feet to move to a standing position. Carefully return the weight to the boxes."]', NULL, '["Snatch_from_Blocks/0.jpg","Snatch_from_Blocks/1.jpg"]', 6, 'sets', 0, 'fedb', 1),
('fe-Speed_Band_Overhead_Triceps', 'Speed Band Overhead Triceps', 'upper arms', 'triceps', '[]', 'bands', 'strength', 'beginner', '["For this exercise anchor a band to the ground. We used an incline bench and anchored the band to the base, standing over the bench. Alternatively, this could be performed standing on the band.","To begin, pull the band behind your head, holding it with a pronated grip and your elbows up. This will be your starting position.","To perform the movement, extend through the elbow to to straighten your arms, ensuring that you keep your upper arm in place.","Pause, and then return to the starting position."]', NULL, '["Speed_Band_Overhead_Triceps/0.jpg","Speed_Band_Overhead_Triceps/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Speed_Box_Squat', 'Speed Box Squat', 'upper legs', 'quadriceps', '["calves","glutes","hamstrings"]', 'barbell', 'powerlifting', 'intermediate', '["Attach bands to the bar that are securely anchored near the ground. You may need to choke the bands to get adequate tension.","Use a box of an appropriate height for this exercise. Load the bar to a weight that still requires effort, but isn''t so heavy that speed is compromised. Typically, that will be between 50-70% of your one rep max.","Position the bar on your upper back, shoulder blades retracted, back arched and everything tight head to toe. This will be the starting position.","Unrack the bar and position yourself in front of the box. Sit back with your hips until you are seated on the box, ensuring that you descend under control and don''t crash onto the surface.","Pause briefly, and explode off of the box, extending through the hips and knees."]', NULL, '["Speed_Box_Squat/0.jpg","Speed_Box_Squat/1.jpg"]', 6, 'sets', 0, 'fedb', 1),
('fe-Speed_Squats', 'Speed Squats', 'upper legs', 'quadriceps', '["calves","glutes","hamstrings","lower back"]', 'barbell', 'strength', 'expert', '["This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.","Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.","Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance which targets overall development; however you can choose any of the three stances discussed in the foot stances section).","Begin to lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.","Begin to raise the bar as fast as possible without involving momentum as you exhale by pushing the floor with the heel of your foot mainly as you straighten the legs again and go back to the starting position. Note: You should perform these exercises as fast as possible but without breaking perfect form and without involving momentum.","Repeat for the recommended amount of repetitions."]', NULL, '["Speed_Squats/0.jpg","Speed_Squats/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Spider_Crawl', 'Spider Crawl', 'waist', 'abdominals', '["chest","shoulders","triceps"]', 'body only', 'strength', 'beginner', '["Begin in a prone position on the floor. Support your weight on your hands and toes, with your feet together and your body straight. Your arms should be bent to 90 degrees. This will be your starting position.","Initiate the movement by raising one foot off of the ground. Externally rotate the leg and bring the knee toward your elbow, as far forward as possible.","Return this leg to the starting position and repeat on the opposite side."]', NULL, '["Spider_Crawl/0.jpg","Spider_Crawl/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Spider_Curl', 'Spider Curl', 'upper arms', 'biceps', '[]', 'e-z curl bar', 'strength', 'beginner', '["Start out by setting the bar on the part of the preacher bench that you would normally sit on. Make sure to align the barbell properly so that it is balanced and will not fall off.","Move to the front side of the preacher bench (the part where the arms usually lay) and position yourself to lay at a 45 degree slant with your torso and stomach pressed against the front side of the preacher bench.","Make sure that your feet (especially the toes) are well positioned on the floor and place your upper arms on top of the pad located on the inside part of the preacher bench.","Use your arms to grab the barbell with a supinated grip (palms facing up) at about shoulder width apart or slightly closer from each other.","Slowly begin to lift the barbell upwards and exhale. Hold the contracted position for a second as you squeeze the biceps.","Slowly begin to bring the barbell back to the starting position as your breathe in. .","Repeat for the recommended amount of repetitions."]', NULL, '["Spider_Curl/0.jpg","Spider_Curl/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Spinal_Stretch', 'Spinal Stretch', 'back', 'middle back', '["lats","lower back","neck","traps"]', 'body only', 'stretching', 'beginner', '["Sit in a chair so your back is straight and your feet planted on the floor.","Interlace your fingers behind your head, elbows out and your chin down.","Twist your upper body to one side about 3 times as far as you can. Then lean forward and twist your torso to reach your elbow to the floor on the inside of your knee.","Return to upright position and then repeat for your other side."]', NULL, '["Spinal_Stretch/0.jpg","Spinal_Stretch/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Split_Clean', 'Split Clean', 'upper legs', 'quadriceps', '["calves","forearms","glutes","hamstrings","lower back","shoulders","traps"]', 'barbell', 'olympic weightlifting', 'intermediate', '["With a barbell on the floor close to the shins, take an overhand grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.","Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. Move the weight with control as you continue to above the knees.","Next comes the second pull, the main source of acceleration for the clean. As the bar approaches the mid-thigh position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the weight; at the end of the second pull, the body should be fully extended, leaning slightly back, with the arms still extended.","As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the arms with the elbows up and out. At peak extension, aggressively pull yourself down, rotating your elbows under the bar as you do so.","Receive the bar with the feet split, aggressively moving one foot forward and one foot back. The bar should be racked onto the protracted shoulders, lightly touching the throat with the hands relaxed. Continue to descend to the bottom position, which will help in the recovery.","Immediately recover by driving through the heels, keeping the torso upright and elbows up. Bring the feet together as you stand up."]', NULL, '["Split_Clean/0.jpg","Split_Clean/1.jpg"]', 6, 'sets', 0, 'fedb', 1),
('fe-Split_Jerk', 'Split Jerk', 'upper legs', 'quadriceps', '["glutes","hamstrings","shoulders","triceps"]', 'barbell', 'olympic weightlifting', 'intermediate', '["Standing with the weight racked on the front of the shoulders, begin with the dip. With your feet directly under your hips, flex the knees without moving the hips backward.","Go down only slightly, and reverse direction as powerfully as possible. Drive through the heels create as much speed and force as possible, and be sure to move your head out of the way as the bar leaves the shoulders. At this moment as the feet leave the floor, the feet must be placed into the receiving position as quickly as possible.","In the brief moment the feet are not actively driving against the platform, the athlete''s effort to push the bar up will drive them down. The feet should be moved to a split stance, one foot forward, one foot back, with the knees partially bent. Receive the bar with the arms locked out overhead.","Return to a standing position, bringing the feet together."]', NULL, '["Split_Jerk/0.jpg","Split_Jerk/1.jpg"]', 6, 'sets', 0, 'fedb', 1),
('fe-Split_Jump', 'Split Jump', 'upper legs', 'quadriceps', '["calves","glutes","hamstrings"]', 'body only', 'plyometrics', 'beginner', '["Assume a lunge stance position with one foot forward with the knee bent, and the rear knee nearly touching the ground.","Ensure that the front knee is over the midline of the foot.","Extending through both legs, jump as high as possible, swinging your arms to gain lift.","As you jump, bring your feet together, and move them back to their initial positions as you land.","Absorb the impact by reverting back to the starting position."]', NULL, '["Split_Jump/0.jpg","Split_Jump/1.jpg"]', 8, 'sets', 0, 'fedb', 1)
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('fe-Split_Snatch', 'Split Snatch', 'upper legs', 'hamstrings', '["calves","forearms","glutes","hamstrings","lower back","quadriceps","shoulders","traps","triceps"]', 'barbell', 'olympic weightlifting', 'expert', '["Begin with a loaded barbell on the floor. The bar should be close to or touching the shins, and a wide grip should be taken on the bar. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the chest up and the head looking forward. The shoulders should be just in front of the bar. This will be the starting position.","Begin the first pull by driving through the front of the heels, raising the bar from the ground. The back angle should stay the same until the bar passes the knees.","Transition into the second pull by extending through the hips knees and ankles, driving the bar up as quickly as possible. The bar should be close to the body. At peak extension, shrug the shoulders and allow the elbows to flex to the side.","As you move your feet into the receiving position, forcefully pull yourself below the bar as you elevate the bar overhead. The feet should move forcefully to a split position, one foot forward one foot back. Receive the bar with your body as low as possible and the arms fully extended overhead.","Keeping the bar aligned over the front of the heels, your head and chest up, drive through heels of the feet to move to a standing position, bringing your feet together.","Carefully return the weight to floor."]', NULL, '["Split_Snatch/0.jpg","Split_Snatch/1.jpg"]', 6, 'sets', 0, 'fedb', 1),
('fe-Split_Squat_with_Dumbbells', 'Split Squat with Dumbbells', 'upper legs', 'quadriceps', '["glutes","hamstrings"]', 'dumbbell', 'strength', 'beginner', '["Position yourself into a staggered stance with the rear foot elevated and front foot forward.","Hold a dumbbell in each hand, letting them hang at the sides. This will be your starting position.","Begin by descending, flexing your knee and hip to lower your body down. Maintain good posture througout the movement. Keep the front knee in line with the foot as you perform the exercise.","At the bottom of the movement, drive through the heel to extend the knee and hip to return to the starting position."]', NULL, '["Split_Squat_with_Dumbbells/0.jpg","Split_Squat_with_Dumbbells/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Split_Squats', 'Split Squats', 'upper legs', 'hamstrings', '["calves","glutes","quadriceps"]', 'body only', 'stretching', 'intermediate', '["Being in a standing position. Jump into a split leg position, with one leg forward and one leg back, flexing the knees and lowering your hips slightly as you do so.","As you descend, immediately reverse direction, standing back up and jumping, reversing the position of your legs. Repeat 5-10 times on each leg."]', NULL, '["Split_Squats/0.jpg","Split_Squats/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Squat_with_Bands', 'Squat with Bands', 'upper legs', 'quadriceps', '["adductors","calves","glutes","hamstrings","lower back"]', 'barbell', 'powerlifting', 'intermediate', '["Set up the bands on the sleeves, secured to either band pegs, the rack, or dumbbells so that there is appropriate tension.","Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wide for more emphasis on the back, glutes, adductors, and hamstrings. Keep your head facing forward.","With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips as much as possible. Ideally, your shins should be perpendicular to the ground. Lower bar position necessitates a greater torso lean to keep the bar over the heels. Continue until you break parallel, which is defined as the crease of the hip being in line with the top of the knee.","Keeping the weight on your heels and pushing your feet and knees out, drive upward as you lead the movement with your head. Continue upward, maintaining tightness head to toe, until you have returned to the starting position."]', NULL, '["Squat_with_Bands/0.jpg","Squat_with_Bands/1.jpg"]', 6, 'sets', 0, 'fedb', 1),
('fe-Squat_with_Chains', 'Squat with Chains', 'upper legs', 'quadriceps', '["adductors","calves","glutes","hamstrings","lower back"]', 'barbell', 'powerlifting', 'intermediate', '["To set up the chains, begin by looping the leader chain over the sleeves of the bar. The heavy chain should be attached using a snap hook. Adjust the length of the lead chain so that a few links are still on the floor at the top of the movement.","Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wide for more emphasis on the back, glutes, adductors, and hamstrings. Keep your head facing forward.","With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips as much as possible. Ideally, your shins should be perpendicular to the ground. Lower bar position necessitates a greater torso lean to keep the bar over the heels. Continue until you break parallel, which is defined as the crease of the hip being in line with the top of the knee.","Keeping the weight on your heels and pushing your feet and knees out, drive upward as you lead the movement with your head. Continue upward, maintaining tightness head to toe, until you have returned to the starting position."]', NULL, '["Squat_with_Chains/0.jpg","Squat_with_Chains/1.jpg"]', 6, 'sets', 0, 'fedb', 1),
('fe-Squat_with_Plate_Movers', 'Squat with Plate Movers', 'upper legs', 'quadriceps', '["abductors","adductors","calves","glutes","hamstrings"]', 'barbell', 'strength', 'intermediate', '["To begin, first set the bar on a rack to just below shoulder level. Position a weight plate on the ground a couple feet back from the rack. Once the bar is loaded, step under it and place the back of your shoulders across it.","Hold on to the bar with both hands and lift it off the rack by first pushing with your legs and at the same time straighten your torso.","Step away from the rack and adopt a wide stance with the toes slightly pointed out, with one foot on the weight plate. Keep your head up at all times. This will be your starting position.","Begin to slowly lower the bar by bending the knees and hips. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees.","Raise the bar as you exhale by pushing the floor with the heels of your feet as you extend the hips and knees.","At the top of the movement, side step, bringing your feet together on the opposite side of the plate.","Using your inside foot, push the weight plate, sliding it across the floor to where you were just standing.","Place your inside foot on the weight plate, adopting a wide stance for the next repetition."]', NULL, '["Squat_with_Plate_Movers/0.jpg","Squat_with_Plate_Movers/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Stairmaster', 'Stairmaster', 'cardio', 'quadriceps', '["calves","glutes","hamstrings"]', 'machine', 'cardio', 'intermediate', '["To begin, step onto the stairmaster and select the desired option from the menu. You can choose a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise.","Pump your legs up and down in an established rhythm, driving the pedals down but not all the way to the floor. It is recommended that you maintain your grip on the handles so that you don''t fall. The handles can be used to monitor your heart rate to help you stay at an appropriate intensity.","Stairmasters offer convenience, cardiovascular benefits, and usually have less impact than running outside. They are typically much harder than other cardio equipment. A 150 lb person will typically burn over 300 calories in 30 minutes, compared to about 175 calories walking."]', NULL, '["Stairmaster/0.jpg","Stairmaster/1.jpg"]', 9, 'time', 0, 'fedb', 1),
('fe-Standing_Alternating_Dumbbell_Press', 'Standing Alternating Dumbbell Press', 'shoulders', 'shoulders', '["triceps"]', 'dumbbell', 'strength', 'beginner', '["Stand with a dumbbell in each hand. Raise the dumbbells to your shoulders with your palms facing forward and your elbows pointed out. This will be your starting position.","Extend one arm to press the dumbbell straight up, keeping your off hand in place. Do not lean or jerk the weight during the movement.","After a brief pause, return the weight to the starting position.","Repeat for the opposite side, continuing to alternate between arms."]', NULL, '["Standing_Alternating_Dumbbell_Press/0.jpg","Standing_Alternating_Dumbbell_Press/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Standing_Barbell_Press_Behind_Neck', 'Standing Barbell Press Behind Neck', 'shoulders', 'shoulders', '["triceps"]', 'barbell', 'strength', 'intermediate', '["This exercise is best performed inside a squat rack for easier pick up of the bar. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.","Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.","Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Your back should be kept straight while performing this exercise. This will be your starting position.","Elevate the barbell overhead by fully extending your arms while breathing out.","Hold the contraction for a second and lower the barbell back down to the starting position by inhaling.","Repeat for the recommended amount of repetitions."]', NULL, '["Standing_Barbell_Press_Behind_Neck/0.jpg","Standing_Barbell_Press_Behind_Neck/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Standing_Biceps_Cable_Curl', 'Standing Biceps Cable Curl', 'upper arms', 'biceps', '[]', 'cable', 'strength', 'beginner', '["Stand up with your torso upright while holding a cable curl bar that is attached to a low pulley. Grab the cable bar at shoulder width and keep the elbows close to the torso. The palm of your hands should be facing up (supinated grip). This will be your starting position.","While holding the upper arms stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second as you squeeze the muscle.","Slowly begin to bring the curl bar back to starting position as your breathe in.","Repeat for the recommended amount of repetitions."]', NULL, '["Standing_Biceps_Cable_Curl/0.jpg","Standing_Biceps_Cable_Curl/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Standing_Biceps_Stretch', 'Standing Biceps Stretch', 'upper arms', 'biceps', '["chest","shoulders"]', 'other', 'stretching', 'beginner', '["Clasp your hands behind your back with your palms together, straighten arms and then rotate them so your palms face downward.","Raise your arms up and hold until you feel a stretch in your biceps."]', NULL, '["Standing_Biceps_Stretch/0.jpg","Standing_Biceps_Stretch/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Standing_Bradford_Press', 'Standing Bradford Press', 'shoulders', 'shoulders', '["triceps"]', 'barbell', 'strength', 'beginner', '["Place a loaded bar at shoulder level in a rack. With a pronated grip at shoulder width, begin with the bar racked across the front of your shoulders. This is your starting position.","Initiate the lift by extending the elbows to press the bar overhead. Avoid locking out the elbow as you move the weight behind your head.","Lower the bar down to the back of the head until your elbow forms a right angle.","Lift the bar back over your head by extending the elbows","Lower the bar down to the starting position.","Alternate in this manner until you complete the recommended amount of repetitions."]', NULL, '["Standing_Bradford_Press/0.jpg","Standing_Bradford_Press/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Standing_Cable_Chest_Press', 'Standing Cable Chest Press', 'chest', 'chest', '["shoulders","triceps"]', 'cable', 'strength', 'beginner', '["Position dual pulleys to chest height and select an appropriate weight. Stand a foot or two in front of the cables, holding one in each hand. You can stagger your stance for better stability.","Position the upper arm at a 90 degree angle with the shoulder blades together. This will be your starting position.","Keeping the rest of the body stationary, extend through the elbows to press the handles forward, drawing them together in front of you.","Pause at the top of the motion, and return to the starting position."]', NULL, '["Standing_Cable_Chest_Press/0.jpg","Standing_Cable_Chest_Press/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Standing_Cable_Wood_Chop', 'Standing Cable Wood Chop', 'waist', 'abdominals', '["shoulders"]', 'cable', 'strength', 'beginner', '["Connect a standard handle to a tower, and move the cable to the highest pulley position.","With your side to the cable, grab the handle with one hand and step away from the tower. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable. Your outstretched arm should be aligned with the cable.","With your feet positioned shoulder width apart, reach upward with your other hand and grab the handle with both hands. Your arms should still be fully extended.","In one motion, pull the handle down and across your body to your front knee while rotating your torso.","Keep your back and arms straight and core tight while you pivot your back foot and bend your knees to get a full range of motion.","Maintain your stance and straight arms. Return to the neutral position in a slow and controlled manner.","Repeat to failure.","Then, reposition and repeat the same series of movements on the opposite side."]', NULL, '["Standing_Cable_Wood_Chop/0.jpg","Standing_Cable_Wood_Chop/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Standing_Calf_Raises', 'Standing Calf Raises', 'lower legs', 'calves', '[]', 'machine', 'strength', 'beginner', '["Adjust the padded lever of the calf raise machine to fit your height.","Place your shoulders under the pads provided and position your toes facing forward (or using any of the two other positions described at the beginning of the chapter). The balls of your feet should be secured on top of the calf block with the heels extending off it. Push the lever up by extending your hips and knees until your torso is standing erect. The knees should be kept with a slight bend; never locked. Toes should be facing forward, outwards or inwards as described at the beginning of the chapter. This will be your starting position.","Raise your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.","Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.","Repeat for the recommended amount of repetitions."]', NULL, '["Standing_Calf_Raises/0.jpg","Standing_Calf_Raises/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Standing_Concentration_Curl', 'Standing Concentration Curl', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', 'beginner', '["Taking a dumbbell in your working hand, lean forward. Allow your working arm to hang perpendicular to the ground with the elbow pointing out. This will be your starting position.","Flex the elbow to curl the weight, keeping the upper arm stationary. At the top of the repetition, flex the biceps and pause.","Lower the dumbbell back to the starting position.","Repeat the movement for the prescribed amount of repetitions."]', NULL, '["Standing_Concentration_Curl/0.jpg","Standing_Concentration_Curl/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Standing_Dumbbell_Press', 'Standing Dumbbell Press', 'shoulders', 'shoulders', '["triceps"]', 'dumbbell', 'strength', 'beginner', '["Standing with your feet shoulder width apart, take a dumbbell in each hand. Raise the dumbbells to head height, the elbows out and about 90 degrees. This will be your starting position.","Maintaining strict technique with no leg drive or leaning back, extend through the elbow to raise the weights together directly above your head.","Pause, and slowly return the weight to the starting position."]', NULL, '["Standing_Dumbbell_Press/0.jpg","Standing_Dumbbell_Press/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Standing_Dumbbell_Straight-Arm_Front_Delt_Raise_Above_Head', 'Standing Dumbbell Straight-Arm Front Delt Raise Above Head', 'shoulders', 'shoulders', '[]', 'dumbbell', 'strength', 'intermediate', '["Hold the dumbbells in front of your thighs, palms facing your thighs.","Keep your arms straight with a slight bend at the elbows but keep them locked. This will be your starting position.","Raise the dumbbells in a semicircular motion to arm''s length overhead as you exhale.","Slowly return to the starting position using the same path as you inhale.","Repeat for the recommended amount of repetitions."]', NULL, '["Standing_Dumbbell_Straight-Arm_Front_Delt_Raise_Above_Head/0.jpg","Standing_Dumbbell_Straight-Arm_Front_Delt_Raise_Above_Head/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Standing_Dumbbell_Upright_Row', 'Standing Dumbbell Upright Row', 'back', 'traps', '["biceps","shoulders"]', 'dumbbell', 'strength', 'beginner', '["Grasp a dumbbell in each hand with a pronated (palms forward) grip that is slightly less than shoulder width. The dumbbells should be resting on top of your thighs. Your arms should be extended with a slight bend at the elbows and your back should be straight. This will be your starting position.","Use your side shoulders to lift the dumbbells as you exhale. The dumbbells should be close to the body as you move it up and the elbows should drive the motion. Continue to lift them until they nearly touch your chin. Tip: Your elbows should drive the motion. As you lift the dumbbells, your elbows should always be higher than your forearms. Also, keep your torso stationary and pause for a second at the top of the movement.","Lower the dumbbells back down slowly to the starting position. Inhale as you perform this portion of the movement.","Repeat for the recommended amount of repetitions."]', NULL, '["Standing_Dumbbell_Upright_Row/0.jpg","Standing_Dumbbell_Upright_Row/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Standing_Elevated_Quad_Stretch', 'Standing Elevated Quad Stretch', 'upper legs', 'quadriceps', '[]', 'other', 'stretching', 'beginner', '["Start by standing with your back about two to three feet away from a bench or step.","Lift one leg behind you and rest your foot on the step,either on your instep or the ball of your foot, whichever you find most comfortable.","Keep your supporting knee slightly bent and avoid letting that knee extend out beyond your toes. Switch sides."]', NULL, '["Standing_Elevated_Quad_Stretch/0.jpg","Standing_Elevated_Quad_Stretch/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Standing_Gastrocnemius_Calf_Stretch', 'Standing Gastrocnemius Calf Stretch', 'lower legs', 'calves', '["hamstrings"]', 'body only', 'stretching', 'beginner', '["Place your right heel on a step with your knee extended and lean forward to grab your right toe with your right hand. Your left knee should be slightly bent and your back should be straight.","Support your weight on your left leg and place your left hand on your left thigh.","Pull your right toes toward your knee until you feel a stretch in your calf."]', NULL, '["Standing_Gastrocnemius_Calf_Stretch/0.jpg","Standing_Gastrocnemius_Calf_Stretch/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Standing_Hamstring_and_Calf_Stretch', 'Standing Hamstring and Calf Stretch', 'upper legs', 'hamstrings', '[]', 'other', 'stretching', 'beginner', '["Being by looping a belt, band, or rope around one foot. While standing, place that foot forward.","Bend your back leg, while keeping the front one straight. Now raise the toes of your front foot off of the ground and lean forward.","Using the belt, pull on the top of the foot to increase the stretch in the calf. Hold for 10-20 seconds and repeat with the other foot."]', NULL, '["Standing_Hamstring_and_Calf_Stretch/0.jpg","Standing_Hamstring_and_Calf_Stretch/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Standing_Hip_Circles', 'Standing Hip Circles', 'upper legs', 'abductors', '["adductors"]', 'body only', 'stretching', 'beginner', '["Begin standing on one leg, holding to a vertical support.","Raise the unsupported knee to 90 degrees. This will be your starting position.","Open the hip as far as possible, attempting to make a big circle with your knee.","Perform this movement slowly for a number of repetitions, and repeat on the other side."]', NULL, '["Standing_Hip_Circles/0.jpg","Standing_Hip_Circles/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Standing_Hip_Flexors', 'Standing Hip Flexors', 'upper legs', 'quadriceps', '[]', 'body only', 'stretching', 'beginner', '["Stand up straight with the spine vertical, the left foot slightly in front of the right.","Bend both knees and lift the back heel off the floor as you press the right hip forward. You can''t get a thorough, deep stretch in this position, however, because it''s hard to relax the hip flexor and stand on it at the same time. Switch sides."]', NULL, '["Standing_Hip_Flexors/0.jpg","Standing_Hip_Flexors/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Standing_Inner-Biceps_Curl', 'Standing Inner-Biceps Curl', 'upper arms', 'biceps', '[]', 'dumbbell', 'strength', 'intermediate', '["Stand up with a dumbbell in each hand being held at arms length. The elbows should be close to the torso. Your legs should be at about shoulder''s width apart from each other.","Rotate the palms of the hands so that they are facing inward in a neutral position. This will be your starting position.","While holding the upper arms stationary, curl the weights out while contracting the biceps as you breathe out. Your wrist should turn so that when the weights are fully elevated you have supinated grip (palms facing up).","Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Tip: Keep the forearms aligned with your outer deltoids.","Hold the contracted position for a second as you squeeze the biceps.","Slowly begin to bring the dumbbells back to the starting position as your breathe in. Remember to rotate the wrists as you lower the weight in order to switch back to a neutral grip.","Repeat for the recommended amount of repetitions."]', NULL, '["Standing_Inner-Biceps_Curl/0.jpg","Standing_Inner-Biceps_Curl/1.jpg"]', 5, 'sets', 0, 'fedb', 1)
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('fe-Standing_Lateral_Stretch', 'Standing Lateral Stretch', 'waist', 'abdominals', '[]', 'body only', 'stretching', 'beginner', '["Take a slightly wider than hip distance stance with your knees slightly bent.","Place your right hand on your right hip to support the spine.","Raise your left arm in a vertical line and place your left hand behind your head. Keep it there as you incline your torso to the right.","Keep your weight evenly distributed between both legs (don''t lean into your left hip). Switch sides."]', NULL, '["Standing_Lateral_Stretch/0.jpg","Standing_Lateral_Stretch/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Standing_Leg_Curl', 'Standing Leg Curl', 'upper legs', 'hamstrings', '[]', 'machine', 'strength', 'beginner', '["Adjust the machine lever to fit your height and lie with your torso bent at the waist facing forward around 30-45 degrees (since an angled position is more favorable for hamstrings recruitment) with the pad of the lever on the back of your right leg (just a few inches under the calves) and the front of the right leg on top of the machine pad.","Keeping the torso bent forward, ensure your leg is fully stretched and grab the side handles of the machine. Position your toes straight. This will be your starting position.","As you exhale, curl your right leg up as far as possible without lifting the upper leg from the pad. Once you hit the fully contracted position, hold it for a second.","As you inhale, bring the legs back to the initial position. Repeat for the recommended amount of repetitions.","Perform the same exercise now for the left leg."]', NULL, '["Standing_Leg_Curl/0.jpg","Standing_Leg_Curl/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Standing_Long_Jump', 'Standing Long Jump', 'upper legs', 'quadriceps', '["calves","glutes","hamstrings"]', 'body only', 'plyometrics', 'beginner', '["This drill is best done in sand or other soft landing surface. Ensure that you are able to measure distance. Stand in a partial squat stance with feet shoulder width apart.","Utilizing a big arm swing and a countermovement of the legs, jump forward as far as you can.","Attempt to land with your feet out in front you, reaching as far as possible with your legs.","Measure the distance from your landing point to the starting point and track results."]', NULL, '["Standing_Long_Jump/0.jpg","Standing_Long_Jump/1.jpg"]', 8, 'sets', 0, 'fedb', 1),
('fe-Standing_Low-Pulley_Deltoid_Raise', 'Standing Low-Pulley Deltoid Raise', 'shoulders', 'shoulders', '["forearms"]', 'cable', 'strength', 'beginner', '["Start by standing to the right side of a low pulley row. Use your left hand to come across the body and grab a single handle attached to the low pulley with a pronated grip (palms facing down). Rest your arm in front of you. Your right hand should grab the machine for better support and balance.","Make sure that your back is erect and your feet are shoulder width apart from each other. This is the starting position.","Begin to use the left hand and come across your body out until it is elevated to shoulder height while exhaling.","Feel the contraction at the top for a second and begin to slowly lower the handle back down to the original starting position while inhaling.","Repeat for the recommended amount of repetitions.","Switch arms and repeat the exercise."]', NULL, '["Standing_Low-Pulley_Deltoid_Raise/0.jpg","Standing_Low-Pulley_Deltoid_Raise/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Standing_Low-Pulley_One-Arm_Triceps_Extension', 'Standing Low-Pulley One-Arm Triceps Extension', 'upper arms', 'triceps', '["chest","shoulders"]', 'cable', 'strength', 'intermediate', '["Grab a single handle with your left arm next to the low pulley machine. Turn away from the machine keeping the handle to the side of your body with your arm fully extended. Now use both hands to elevate the single handle directly above the head with the palm facing forward. Keep your upper arm completely vertical (perpendicular to the floor) and put your right hand on your left elbow to help keep it steady. This is the starting position.","Keeping your upper arms close to your head (elbows in) and perpendicular to the floor, lower the resistance in a semicircular motion behind your head until your forearms touch your biceps. Tip: The upper arms should remain stationary and only the forearms should move. Breathe in as you perform this step.","Go back to the starting position by using the triceps to raise the single handle. Breathe out as you perform this step.","Repeat for the recommended amount of repetitions.","Switch arms and repeat the exercise."]', NULL, '["Standing_Low-Pulley_One-Arm_Triceps_Extension/0.jpg","Standing_Low-Pulley_One-Arm_Triceps_Extension/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Standing_Military_Press', 'Standing Military Press', 'shoulders', 'shoulders', '["triceps"]', 'barbell', 'strength', 'beginner', '["Start by placing a barbell that is about chest high on a squat rack. Once you have selected the weights, grab the barbell using a pronated (palms facing forward) grip. Make sure to grip the bar wider than shoulder width apart from each other.","Slightly bend the knees and place the barbell on your collar bone. Lift the barbell up keeping it lying on your chest. Take a step back and position your feet shoulder width apart from each other.","Once you pick up the barbell with the correct grip length, lift the bar up over your head by locking your arms. Hold at about shoulder level and slightly in front of your head. This is your starting position.","Lower the bar down to the collarbone slowly as you inhale.","Lift the bar back up to the starting position as you exhale.","Repeat for the recommended amount of repetitions."]', NULL, '["Standing_Military_Press/0.jpg","Standing_Military_Press/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Standing_Olympic_Plate_Hand_Squeeze', 'Standing Olympic Plate Hand Squeeze', 'lower arms', 'forearms', '["biceps"]', 'other', 'strength', 'beginner', '["To begin, stand straight while holding a weight plate by the ridge at arm''s length in each hand using a neutral grip (palms facing in). You feet should be shoulder width apart from each other. This will be your starting position.","Lower the plates until the fingers are nearly extended but can still hold weights. Inhale as you lower the plates.","Now raise the plates back to the starting position as you exhale by closing your hands.","Repeat for the recommended amount of repetitions prescribed in your program."]', NULL, '["Standing_Olympic_Plate_Hand_Squeeze/0.jpg","Standing_Olympic_Plate_Hand_Squeeze/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Standing_One-Arm_Cable_Curl', 'Standing One-Arm Cable Curl', 'upper arms', 'biceps', '[]', 'cable', 'strength', 'intermediate', '["Start out by grabbing single handle next to the low pulley machine. Make sure you are far enough from the machine so that your arm is supporting the weight.","Make sure that your upper arm is stationary, perpendicular to the floor with elbows in and palms facing forward. Your non lifting arm should be grabbing your waist. This will allow you to keep your balance.","Slowly begin to curl the single handle upwards while keeping the upper arm stationary until your forearm touches your bicep while exhaling. Tip: Only the forearm should move.","Hold the contraction position as you squeeze the bicep and then lower the single handle back down to the starting position as you inhale.","Repeat for the recommended amount of repetitions.","Switch arms while performing this exercise."]', NULL, '["Standing_One-Arm_Cable_Curl/0.jpg","Standing_One-Arm_Cable_Curl/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Standing_One-Arm_Dumbbell_Triceps_Extension', 'Standing One-Arm Dumbbell Triceps Extension', 'upper arms', 'triceps', '["chest","shoulders"]', 'dumbbell', 'strength', 'beginner', '["To begin, stand up with a dumbbell held in one hand. Your feet should be about shoulder width apart from each other. Now fully extend the arm with the dumbbell over your head. Tip: The small finger of your hand should be facing the ceiling and the palm of your hand should be facing forward. The dumbbell should be above your head.","This will be your starting position.","Keeping your upper arm close to your head (elbows in) and perpendicular to the floor, lower the resistance in a semicircular motion behind your head until your forearm touch your bicep. Tip: The upper arm should remain stationary and only the forearm should move. Breathe in as you perform this step.","Go back to the starting position by using the triceps to raise the dumbbell. Breathe out as you perform this step.","Repeat for the recommended amount of repetitions.","Switch arms and repeat the exercise."]', NULL, '["Standing_One-Arm_Dumbbell_Triceps_Extension/0.jpg","Standing_One-Arm_Dumbbell_Triceps_Extension/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Standing_Palms-Up_Barbell_Behind_The_Back_Wrist_Curl', 'Standing Palms-Up Barbell Behind The Back Wrist Curl', 'lower arms', 'forearms', '[]', 'barbell', 'strength', 'beginner', '["Start by standing straight and holding a barbell behind your glutes at arm''s length while using a pronated grip (palms will be facing back away from the glutes) and having your hands shoulder width apart from each other.","You should be looking straight forward while your feet are shoulder width apart from each other. This is the starting position.","While exhaling, slowly elevate the barbell up by curling your wrist in a semi-circular motion towards the ceiling. Note: Your wrist should be the only body part moving for this exercise.","Hold the contraction for a second and lower the barbell back down to the starting position while inhaling.","Repeat for the recommended amount of repetitions.","When finished, lower the barbell down to the squat rack or the floor by bending the knees. Tip: It is easiest to either pick it up from a squat rack or have a partner hand it to you."]', NULL, '["Standing_Palms-Up_Barbell_Behind_The_Back_Wrist_Curl/0.jpg","Standing_Palms-Up_Barbell_Behind_The_Back_Wrist_Curl/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Standing_Pelvic_Tilt', 'Standing Pelvic Tilt', 'back', 'lower back', '["glutes"]', 'body only', 'stretching', 'beginner', '["Start off with your feet hip-distance apart.","Bend your knees slightly to keep them soft and springy.","You may want to move your pelvis forward and backward and back few times before holding the tailbone forward in this stretch."]', NULL, '["Standing_Pelvic_Tilt/0.jpg","Standing_Pelvic_Tilt/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Standing_Rope_Crunch', 'Standing Rope Crunch', 'waist', 'abdominals', '[]', 'cable', 'strength', 'beginner', '["Attach a rope to a high pulley and select an appropriate weight.","Stand with your back to the cable tower. Take the rope with both hands over your shoulders, holding it to your upper chest. This will be your starting position.","Perform the movement by flexing the spine, crunching the weight down as far as you can.","Hold the peak contraction for a moment before returning to the starting position."]', NULL, '["Standing_Rope_Crunch/0.jpg","Standing_Rope_Crunch/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Standing_Soleus_And_Achilles_Stretch', 'Standing Soleus And Achilles Stretch', 'lower legs', 'calves', '[]', 'body only', 'stretching', 'beginner', '["Stand with your feet hip-distance apart, one foot slightly in front of the other.","Bend both knees, keeping your back heel on the floor. Switch sides."]', NULL, '["Standing_Soleus_And_Achilles_Stretch/0.jpg","Standing_Soleus_And_Achilles_Stretch/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Standing_Toe_Touches', 'Standing Toe Touches', 'upper legs', 'hamstrings', '["calves"]', 'body only', 'stretching', 'beginner', '["Stand with some space in front and behind you.","Bend at the waist, keeping your legs straight, until you can relax and let your upper body hang down in front of you. Let your arms and hands hang down naturally. Hold for 10 to 20 seconds."]', NULL, '["Standing_Toe_Touches/0.jpg","Standing_Toe_Touches/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Standing_Towel_Triceps_Extension', 'Standing Towel Triceps Extension', 'upper arms', 'triceps', '[]', 'body only', 'strength', 'beginner', '["To begin, stand up with both arms fully extended above the head holding one end of a towel with both hands. Your elbows should be in and the arms perpendicular to the floor with the palms facing each other while your feet should be shoulder width apart from each other. This is the starting position.","Now communicate with your partner so that he/she can grip the other side of the towel to apply resistance. Keeping your upper arms close to your head (elbows in) and perpendicular to the floor, lower the resistance in a semicircular motion behind your head until your forearms touch your biceps. Tip: The upper arms should remain stationary and only the forearms should move. Breathe in as you perform this step.","Go back to the starting position by using the triceps to raise the towel. Breathe out as you perform this step.","Repeat for the recommended amount of repetitions."]', NULL, '["Standing_Towel_Triceps_Extension/0.jpg","Standing_Towel_Triceps_Extension/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Standing_Two-Arm_Overhead_Throw', 'Standing Two-Arm Overhead Throw', 'shoulders', 'shoulders', '["chest","lats"]', 'medicine ball', 'plyometrics', 'beginner', '["Stand with your feet shoulder width apart holding a medicine ball in both hands. To begin, reach the medicine ball deep behind your head as you bend the knees slightly and lean back.","Violently throw the ball forward, flexing at the hip and using your whole body to complete the movement.","The medicine ball can be thrown to a partner or to a wall, receiving it as it bounces back."]', NULL, '["Standing_Two-Arm_Overhead_Throw/0.jpg","Standing_Two-Arm_Overhead_Throw/1.jpg"]', 8, 'sets', 0, 'fedb', 1),
('fe-Star_Jump', 'Star Jump', 'upper legs', 'quadriceps', '["calves","glutes","hamstrings","shoulders"]', 'body only', 'plyometrics', 'beginner', '["Begin in a relaxed stance with your feet shoulder width apart and hold your arms close to the body.","To initiate the move, squat down halfway and explode back up as high as possible. Fully extend your entire body, spreading your legs and arms away from the body.","As you land, bring your limbs back in and absorb your impact through the legs."]', NULL, '["Star_Jump/0.jpg","Star_Jump/1.jpg"]', 8, 'sets', 0, 'fedb', 1),
('fe-Step-up_with_Knee_Raise', 'Step-up with Knee Raise', 'upper legs', 'glutes', '["hamstrings","quadriceps"]', 'body only', 'strength', 'beginner', '["Stand facing a box or bench of an appropriate height with your feet together. This will be your starting position.","Begin the movement by stepping up, putting your left foot on the top of the bench. Extend through the hip and knee of your front leg to stand up on the box. As you stand on the box with your left leg, flex your right knee and hip, bringing your knee as high as you can.","Reverse this motion to step down off the box, and then repeat the sequence on the opposite leg."]', NULL, '["Step-up_with_Knee_Raise/0.jpg","Step-up_with_Knee_Raise/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Step_Mill', 'Step Mill', 'cardio', 'quadriceps', '["calves","glutes","hamstrings"]', 'machine', 'cardio', 'intermediate', '["To begin, step onto the stepmill and select the desired option from the menu. You can choose a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. Use caution so that you don''t trip as you climb the stairs. It is recommended that you maintain your grip on the handles so that you don''t fall.","Stepmills offer convenience, cardiovascular benefits, and usually have less impact than running outside while offering a similar rate of calories burned. They are typically much harder than other cardio equipment. A 150 lb person will typically burn over 300 calories in 30 minutes, compared to about 175 calories walking."]', NULL, '["Step_Mill/0.jpg","Step_Mill/1.jpg"]', 9, 'time', 0, 'fedb', 1),
('fe-Stiff-Legged_Barbell_Deadlift', 'Stiff-Legged Barbell Deadlift', 'upper legs', 'hamstrings', '["glutes","lower back"]', 'barbell', 'strength', 'intermediate', '["Grasp a bar using an overhand grip (palms facing down). You may need some wrist wraps if using a significant amount of weight.","Stand with your torso straight and your legs spaced using a shoulder width or narrower stance. The knees should be slightly bent. This is your starting position.","Keeping the knees stationary, lower the barbell to over the top of your feet by bending at the hips while keeping your back straight. Keep moving forward as if you were going to pick something from the floor until you feel a stretch on the hamstrings. Inhale as you perform this movement.","Start bringing your torso up straight again by extending your hips until you are back at the starting position. Exhale as you perform this movement.","Repeat for the recommended amount of repetitions."]', NULL, '["Stiff-Legged_Barbell_Deadlift/0.jpg","Stiff-Legged_Barbell_Deadlift/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Stiff-Legged_Dumbbell_Deadlift', 'Stiff-Legged Dumbbell Deadlift', 'upper legs', 'hamstrings', '["glutes","lower back"]', 'dumbbell', 'strength', 'beginner', '["Grasp a couple of dumbbells holding them by your side at arm''s length.","Stand with your torso straight and your legs spaced using a shoulder width or narrower stance. The knees should be slightly bent. This is your starting position.","Keeping the knees stationary, lower the dumbbells to over the top of your feet by bending at the waist while keeping your back straight. Keep moving forward as if you were going to pick something from the floor until you feel a stretch on the hamstrings. Exhale as you perform this movement","Start bringing your torso up straight again by extending your hips and waist until you are back at the starting position. Inhale as you perform this movement.","Repeat for the recommended amount of repetitions."]', NULL, '["Stiff-Legged_Dumbbell_Deadlift/0.jpg","Stiff-Legged_Dumbbell_Deadlift/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Stomach_Vacuum', 'Stomach Vacuum', 'waist', 'abdominals', '[]', 'body only', 'stretching', 'beginner', '["To begin, stand straight with your feet shoulder width apart from each other. Place your hands on your hips. This is the starting position.","Now slowly inhale as much air as possible and then start to exhale as much as possible while bringing your stomach in as much as possible and hold this position. Try to visualize your navel touching your backbone.","One isometric contraction is around 20 seconds. During the 20 second hold, try to breathe normally. Then inhale and bring your stomach back to the starting position.","Once you have practiced this exercise, try to perform this exercise for longer than 20 seconds. Tip: You can work your way up to 40-60 seconds.","Repeat for the recommended amount of sets."]', NULL, '["Stomach_Vacuum/0.jpg","Stomach_Vacuum/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Straight-Arm_Pulldown', 'Straight-Arm Pulldown', 'back', 'lats', '[]', 'cable', 'strength', 'beginner', '["You will start by grabbing the wide bar from the top pulley of a pulldown machine and using a wider than shoulder-width pronated (palms down) grip. Step backwards two feet or so.","Bend your torso forward at the waist by around 30-degrees with your arms fully extended in front of you and a slight bend at the elbows. If your arms are not fully extended then you need to step a bit more backwards until they are. Once your arms are fully extended and your torso is slightly bent at the waist, tighten the lats and then you are ready to begin.","While keeping the arms straight, pull the bar down by contracting the lats until your hands are next to the side of the thighs. Breathe out as you perform this step.","While keeping the arms straight, go back to the starting position while breathing in.","Repeat for the recommended amount of repetitions."]', NULL, '["Straight-Arm_Pulldown/0.jpg","Straight-Arm_Pulldown/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Straight_Bar_Bench_Mid_Rows', 'Straight Bar Bench Mid Rows', 'back', 'middle back', '["biceps","lats"]', 'barbell', 'strength', 'beginner', '["Place a loaded barbell on the end of a bench. Standing on the bench behind the bar, take a medium, pronated grip. Stand with your hips back and chest up, maintaining a neutral spine. This will be your starting position.","Row the bar to your torso by retracting the shoulder blades and flexing the elbows. Use a controlled movement with no jerking.","After a brief pause, slowly return the bar to the starting position, ensuring to go all the way down."]', NULL, '["Straight_Bar_Bench_Mid_Rows/0.jpg","Straight_Bar_Bench_Mid_Rows/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Straight_Raises_on_Incline_Bench', 'Straight Raises on Incline Bench', 'shoulders', 'shoulders', '["traps"]', 'barbell', 'strength', 'beginner', '["Place a bar on the ground behind the head of an incline bench.","Lay on the bench face down. With a pronated grip, pick the barbell up from the floor, keeping your arms straight. Allow the bar to hang straight down. This will be your starting position.","To begin, raise the barbell out in front of your head while keeping your arms extended.","Return to the starting position."]', NULL, '["Straight_Raises_on_Incline_Bench/0.jpg","Straight_Raises_on_Incline_Bench/1.jpg"]', 5, 'sets', 0, 'fedb', 1)
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('fe-Stride_Jump_Crossover', 'Stride Jump Crossover', 'upper legs', 'quadriceps', '["abductors","adductors","calves","hamstrings"]', 'other', 'plyometrics', 'beginner', '["Stand to the side of a box with your inside foot on top of it, close to the edge.","Begin by swinging the arms upward as you push through the top leg, jumping upward as high as possible. Attempt to drive the opposite knee upward.","Land in the opposite position that you started, on the opposite side of the box. The foot that was initially on the box will now be on the ground, with the opposite foot now on the box.","Repeat the movement, crossing back over to the other side."]', NULL, '["Stride_Jump_Crossover/0.jpg","Stride_Jump_Crossover/1.jpg"]', 8, 'sets', 0, 'fedb', 1),
('fe-Sumo_Deadlift', 'Sumo Deadlift', 'upper legs', 'hamstrings', '["adductors","forearms","glutes","lower back","middle back","quadriceps","traps"]', 'barbell', 'powerlifting', 'intermediate', '["Begin with a bar loaded on the ground. Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should be directly below the shoulders, inside the legs, and you can use a pronated grip, a mixed grip, or hook grip. Relax the shoulders, which in effect lengthens your arms.","Take a breath, and then lower your hips, looking forward with your head with your chest up. Drive through the floor, spreading your feet apart, with your weight on the back half of your feet. Extend through the hips and knees.","As the bar passes through the knees, lean back and drive the hips into the bar, pulling your shoulder blades together.","Return the weight to the ground by bending at the hips and controlling the weight on the way down."]', NULL, '["Sumo_Deadlift/0.jpg","Sumo_Deadlift/1.jpg"]', 6, 'sets', 0, 'fedb', 1),
('fe-Sumo_Deadlift_with_Bands', 'Sumo Deadlift with Bands', 'upper legs', 'hamstrings', '["adductors","forearms","glutes","lower back","middle back","quadriceps","traps"]', 'barbell', 'powerlifting', 'intermediate', '["To deadlift with short bands, simply loop them over the bar before you start, and step into them to set up. Ensure that they under the back half of your foot, directly where you are driving into the floor.","Begin with a bar loaded on the ground. Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should be directly below the shoulders, inside the legs, and you can use a pronated grip, a mixed grip, or hook grip.","Take a breath, and then lower your hips, looking forward with your head with your chest up. Drive through the floor, spreading your feet apart, with your weight on the back half of your feet. Extend through the hips and knees.","As the bar passes through the knees, lean back and drive the hips into the bar, pulling your shoulder blades together.","Return the weight to the ground by bending at the hips and controlling the weight on the way down."]', NULL, '["Sumo_Deadlift_with_Bands/0.jpg","Sumo_Deadlift_with_Bands/1.jpg"]', 6, 'sets', 0, 'fedb', 1),
('fe-Sumo_Deadlift_with_Chains', 'Sumo Deadlift with Chains', 'upper legs', 'hamstrings', '["abductors","adductors","forearms","glutes","lower back","middle back","quadriceps","traps"]', 'barbell', 'powerlifting', 'intermediate', '["You can attach the chains to the sleeves of the bar, or just drape the middle over the bar so there is a greater weight increase as you lift. Attempt to keep the ends of the chains away from the plates so you don''t hit them when you lower the weight.","Begin with a bar loaded on the ground. Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should be directly below the shoulders, inside the legs, and you can use a pronated grip, a mixed grip, or hook grip. Relax the shoulders, which in effect lengthens your arms.","Take a breath, and then lower your hips, looking forward with your head with your chest up. Drive through the floor, spreading your feet apart, with your weight on the back half of your feet. Extend through the hips and knees.","As the bar passes through the knees, lean back and drive the hips into the bar, pulling your shoulder blades together.","Return the weight to the ground by bending at the hips and controlling the weight on the way down."]', NULL, '["Sumo_Deadlift_with_Chains/0.jpg","Sumo_Deadlift_with_Chains/1.jpg"]', 6, 'sets', 0, 'fedb', 1),
('fe-Superman', 'Superman', 'back', 'lower back', '["glutes","hamstrings"]', 'body only', 'stretching', 'beginner', '["To begin, lie straight and face down on the floor or exercise mat. Your arms should be fully extended in front of you. This is the starting position.","Simultaneously raise your arms, legs, and chest off of the floor and hold this contraction for 2 seconds. Tip: Squeeze your lower back to get the best results from this exercise. Remember to exhale during this movement. Note: When holding the contracted position, you should look like superman when he is flying.","Slowly begin to lower your arms, legs and chest back down to the starting position while inhaling.","Repeat for the recommended amount of repetitions prescribed in your program."]', NULL, '["Superman/0.jpg","Superman/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Supine_Chest_Throw', 'Supine Chest Throw', 'upper arms', 'triceps', '["chest","shoulders"]', 'medicine ball', 'plyometrics', 'beginner', '["This drill is great for chest passes when you lack a partner or a wall of sufficient strength. Lay on the ground on your back with your knees bent.","Begin with the ball on your chest, held with both hands on the bottom.","Explode up, extending through the elbow to throw the ball directly above you as high as possible.","Catch the ball with both hands as it comes down."]', NULL, '["Supine_Chest_Throw/0.jpg","Supine_Chest_Throw/1.jpg"]', 8, 'sets', 0, 'fedb', 1),
('fe-Supine_One-Arm_Overhead_Throw', 'Supine One-Arm Overhead Throw', 'waist', 'abdominals', '["chest","lats","shoulders"]', 'medicine ball', 'plyometrics', 'beginner', '["Lay on the ground on your back with your knees bent. Hold the ball with one hand, extending the arm fully behind your head. This will be your starting position.","Initiate the movement at the shoulder, throwing the ball directly forward of you as you sit up, attempting to go for maximum distance.","The ball can be thrown to a partner or bounced off of a wall."]', NULL, '["Supine_One-Arm_Overhead_Throw/0.jpg","Supine_One-Arm_Overhead_Throw/1.jpg"]', 8, 'sets', 0, 'fedb', 1),
('fe-Supine_Two-Arm_Overhead_Throw', 'Supine Two-Arm Overhead Throw', 'waist', 'abdominals', '["chest","lats","shoulders"]', 'medicine ball', 'plyometrics', 'beginner', '["Lay on the ground on your back with your knees bent.","Hold the ball with both hands, extending the arms fully behind your head. This will be your starting position.","Initiate the movement at the shoulder, throwing the ball directly forward of you as you sit up, attempting to go for maximum distance.","The ball can be thrown to a partner or bounced off of a wall."]', NULL, '["Supine_Two-Arm_Overhead_Throw/0.jpg","Supine_Two-Arm_Overhead_Throw/1.jpg"]', 8, 'sets', 0, 'fedb', 1),
('fe-Suspended_Fallout', 'Suspended Fallout', 'waist', 'abdominals', '["chest","lower back","shoulders"]', 'other', 'strength', 'intermediate', '["Adjust the straps so the handles are at an appropriate height, below waist level.","Begin standing and grasping the handles. Lean into the straps, moving to an incline push-up position. This will be your starting position.","Keeping your arms straight, lean further into the suspension straps, bringing your body closer to the ground, allowing your shoulders to extend, raising your arms up and over your head.","Maintain a neutral spine and keep the rest of your body straight, your shoulders being the only joints allowed to move.","Pause during the peak contraction, and then return to the starting position."]', NULL, '["Suspended_Fallout/0.jpg","Suspended_Fallout/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Suspended_Push-Up', 'Suspended Push-Up', 'chest', 'chest', '["shoulders","triceps"]', 'other', 'strength', 'beginner', '["Anchor your suspension straps securely to the top of a rack or other object.","Leaning into the straps, take a handle in each hand and move into a push-up plank position. You should be as close to parallel to the ground as you can manage with your arms fully extended, maintaining good posture.","Maintaining a straight, rigid torso, descend slowly by allowing the elbows to flex.","Continue until your elbows break 90 degrees, pausing before you extend to return to the starting position."]', NULL, '["Suspended_Push-Up/0.jpg","Suspended_Push-Up/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Suspended_Reverse_Crunch', 'Suspended Reverse Crunch', 'waist', 'abdominals', '[]', 'other', 'strength', 'beginner', '["Secure a set of suspension straps with the handles hanging about a foot off of the ground. Move yourself into a pushup plank position facing away from the rack.","Place your feet into the handles. You should maintain a straight posture, not allowing the hips to sag. This will be your starting position.","Begin the movement by flexing the knees and hips, drawing the knees to your torso. As you do so, anteriorly tilt your pelvis, allowing your spine to flex.","At the top of the controlled motion, return to the starting position."]', NULL, '["Suspended_Reverse_Crunch/0.jpg","Suspended_Reverse_Crunch/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Suspended_Row', 'Suspended Row', 'back', 'middle back', '["biceps","lats"]', 'other', 'strength', 'beginner', '["Suspend your straps at around chest height. Take a handle in each hand and lean back. Keep your body erect and your head and chest up. Your arms should be fully extended. This will be your starting position.","Begin by flexing the elbow to initiate the movement. Protract your shoulder blades as you do so.","At the completion of the motion pause, and then return to the starting position."]', NULL, '["Suspended_Row/0.jpg","Suspended_Row/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Suspended_Split_Squat', 'Suspended Split Squat', 'upper legs', 'quadriceps', '["abductors","adductors","calves","glutes","hamstrings"]', 'other', 'strength', 'intermediate', '["Suspend your straps so the handles are 18-30 inches from the floor.","Facing away from the setup, place your rear foot into the handle behind you. Keep your head looking forward and your chest up, with your knee slightly bent. This will be your starting position.","Descend by flexing the knee and hips, lowering yourself to the ground. Keep your weight on the heel of your foot and maintain your posture throughout the exercise.","At the bottom of the movement, reverse the motion, extending through the hip and knee to return to the starting position."]', NULL, '["Suspended_Split_Squat/0.jpg","Suspended_Split_Squat/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Svend_Press', 'Svend Press', 'chest', 'chest', '["forearms","shoulders","triceps"]', 'other', 'strength', 'beginner', '["Begin in a standing position.","Press two lightweight plates together with your hands. Hold the plates together close to your chest to create an isometric contraction in your chest muscles. Your fingers should be pointed forward. This is your starting position.","Squeeze the plates between your palms and extend your arms directly out in front of you in a controlled motion.","Pause at the top of the motion, and then slowly return to the starting position."]', NULL, '["Svend_Press/0.jpg","Svend_Press/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-T-Bar_Row_with_Handle', 'T-Bar Row with Handle', 'back', 'middle back', '["biceps","lats"]', 'barbell', 'strength', 'beginner', '["Position a bar into a landmine or in a corner to keep it from moving. Load an appropriate weight onto your end.","Stand over the bar, and position a Double D row handle around the bar next to the collar. Using your hips and legs, rise to a standing position.","Assume a wide stance with your hips back and your chest up. Your arms should be extended. This will be your starting position.","Pull the weight to your upper abdomen by retracting the shoulder blades and flexing the elbows. Do not jerk the weight or cheat during the movement.","After a brief pause, return to the starting position."]', NULL, '["T-Bar_Row_with_Handle/0.jpg","T-Bar_Row_with_Handle/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Tate_Press', 'Tate Press', 'upper arms', 'triceps', '["chest","shoulders"]', 'dumbbell', 'strength', 'intermediate', '["Lie down on a flat bench with a dumbbell in each hand on top of your thighs. The palms of your hand will be facing each other.","By using your thighs to help you get the dumbbells up, clean the dumbbells one arm at a time so that you can hold them in front of you at shoulder width. Note: when holding the dumbbells in front of you, make sure your arms are wider than shoulder width apart from each other using a pronated (palms forward) grip. Allow your elbows to point out. This is your starting position.","Keeping the upper arms stationary, slowly move the dumbbells in and down in a semi circular motion until they touch the upper chest while inhaling. Keep full control of the dumbbells at all times and do not move the upper arms nor rest the dumbbells on the chest.","As you breathe out, move the dumbbells up using your triceps and the same semi-circular motion but in reverse. Attempt to keep the dumbbells together as they move up. Lock your arms in the contracted position, hold for a second and then start coming down again slowly again. Tip: It should take at least twice as long to go down than to come up.","Repeat the movement for the prescribed amount of repetitions of your training program."]', NULL, '["Tate_Press/0.jpg","Tate_Press/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-The_Straddle', 'The Straddle', 'upper legs', 'hamstrings', '["adductors","calves"]', 'body only', 'stretching', 'beginner', '["Begin in a seated, upright position. Start by extending your legs in front of you in a V.","With your hands on the floor, lean forward as far as possible. Hold for 10 to 20 seconds."]', NULL, '["The_Straddle/0.jpg","The_Straddle/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Thigh_Abductor', 'Thigh Abductor', 'upper legs', 'abductors', '["glutes"]', 'machine', 'strength', 'beginner', '["To begin, sit down on the abductor machine and select a weight you are comfortable with. When your legs are positioned properly, grip the handles on each side. Your entire upper body (from the waist up) should be stationary. This is the starting position.","Slowly press against the machine with your legs to move them away from each other while exhaling.","Feel the contraction for a second and begin to move your legs back to the starting position while breathing in. Note: Remember to keep your upper body stationary to prevent any injuries from occurring.","Repeat for the recommended amount of repetitions."]', NULL, '["Thigh_Abductor/0.jpg","Thigh_Abductor/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Thigh_Adductor', 'Thigh Adductor', 'upper legs', 'adductors', '["glutes","hamstrings"]', 'machine', 'strength', 'beginner', '["To begin, sit down on the adductor machine and select a weight you are comfortable with. When your legs are positioned properly on the leg pads of the machine, grip the handles on each side. Your entire upper body (from the waist up) should be stationary. This is the starting position.","Slowly press against the machine with your legs to move them towards each other while exhaling.","Feel the contraction for a second and begin to move your legs back to the starting position while breathing in. Note: Remember to keep your upper body stationary and avoid fast jerking motions in order to prevent any injuries from occurring.","Repeat for the recommended amount of repetitions."]', NULL, '["Thigh_Adductor/0.jpg","Thigh_Adductor/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Tire_Flip', 'Tire Flip', 'upper legs', 'quadriceps', '["calves","chest","forearms","glutes","hamstrings","lower back","shoulders","traps","triceps"]', 'other', 'strongman', 'intermediate', '["Begin by gripping the bottom of the tire on the tread, and position your feet back a bit. Your chest should be driving into the tire.","To lift the tire, extend through the hips, knees, and ankles, driving into the tire and up.","As the tire reaches a 45 degree angle, step forward and drive a knee into the tire. As you do so adjust your grip to the upper portion of the tire and push it forward as hard as possible to complete the turn. Repeat as necessary."]', NULL, '["Tire_Flip/0.jpg","Tire_Flip/1.jpg"]', 7, 'sets', 0, 'fedb', 1),
('fe-Toe_Touchers', 'Toe Touchers', 'waist', 'abdominals', '[]', 'body only', 'stretching', 'beginner', '["To begin, lie down on the floor or an exercise mat with your back pressed against the floor. Your arms should be lying across your sides with the palms facing down.","Your legs should be touching each other. Slowly elevate your legs up in the air until they are almost perpendicular to the floor with a slight bend at the knees. Your feet should be parallel to the floor.","Move your arms so that they are fully extended at a 45 degree angle from the floor. This is the starting position.","While keeping your lower back pressed against the floor, slowly lift your torso and use your hands to try and touch your toes. Remember to exhale while perform this part of the exercise.","Slowly begin to lower your torso and arms back down to the starting position while inhaling. Remember to keep your arms straight out pointing towards your toes.","Repeat for the recommended amount of repetitions."]', NULL, '["Toe_Touchers/0.jpg","Toe_Touchers/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Torso_Rotation', 'Torso Rotation', 'waist', 'abdominals', '[]', 'exercise ball', 'stretching', 'beginner', '["Stand upright holding an exercise ball with both hands. Extend your arms so the ball is straight out in front of you. This will be your starting position.","Rotate your torso to one side, keeping your eyes on the ball as you move. Now, rotate back to the opposite direction. Repeat for 10-20 repetitions."]', NULL, '["Torso_Rotation/0.jpg","Torso_Rotation/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Trail_Running_Walking', 'Trail Running/Walking', 'cardio', 'quadriceps', '["calves","glutes","hamstrings"]', 'body only', 'cardio', 'beginner', '["Running or hiking on trails will get the blood pumping and heart beating almost immediately. Make sure you have good shoes. While you use the muscles in your calves and buttocks to pull yourself up a hill, the knees, joints and ankles absorb the bulk of the pounding coming back down. Take smaller steps as you walk downhill, keep your knees bent to reduce the impact and slow down to avoid falling.","A 150 lb person can burn over 200 calories for 30 minutes walking uphill, compared to 175 on a flat surface. If running the trail, a 150 lb person can burn well over 500 calories in 30 minutes."]', NULL, '["Trail_Running_Walking/0.jpg","Trail_Running_Walking/1.jpg"]', 9.8, 'time', 0, 'fedb', 1),
('fe-Trap_Bar_Deadlift', 'Trap Bar Deadlift', 'upper legs', 'quadriceps', '["glutes","hamstrings"]', 'other', 'strength', 'beginner', '["For this exercise load a trap bar, also known as a hex bar, to an appropriate weight resting on the ground. Stand in the center of the apparatus and grasp both handles.","Lower your hips, look forward with your head and keep your chest up.","Begin the movement by driving through the heels and extend your hips and knees. Avoid rounding your back at all times.","At the completion of the movement, lower the weight back to the ground under control."]', NULL, '["Trap_Bar_Deadlift/0.jpg","Trap_Bar_Deadlift/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Tricep_Dumbbell_Kickback', 'Tricep Dumbbell Kickback', 'upper arms', 'triceps', '[]', 'dumbbell', 'strength', 'beginner', '["Start with a dumbbell in each hand and your palms facing your torso. Keep your back straight with a slight bend in the knees and bend forward at the waist. Your torso should be almost parallel to the floor. Make sure to keep your head up. Your upper arms should be close to your torso and parallel to the floor. Your forearms should be pointed towards the floor as you hold the weights. There should be a 90-degree angle formed between your forearm and upper arm. This is your starting position.","Now, while keeping your upper arms stationary, exhale and use your triceps to lift the weights until the arm is fully extended. Focus on moving the forearm.","After a brief pause at the top contraction, inhale and slowly lower the dumbbells back down to the starting position.","Repeat the movement for the prescribed amount of repetitions."]', NULL, '["Tricep_Dumbbell_Kickback/0.jpg","Tricep_Dumbbell_Kickback/1.jpg"]', 5, 'sets', 0, 'fedb', 1)
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('fe-Tricep_Side_Stretch', 'Tricep Side Stretch', 'upper arms', 'triceps', '["shoulders"]', 'body only', 'stretching', 'beginner', '["Bring right arm across your body and over your left shoulder, holding your elbow with your left hand, until you feel a stretch in your tricep. Then repeat for your other arm."]', NULL, '["Tricep_Side_Stretch/0.jpg","Tricep_Side_Stretch/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Triceps_Overhead_Extension_with_Rope', 'Triceps Overhead Extension with Rope', 'upper arms', 'triceps', '[]', 'cable', 'strength', 'beginner', '["Attach a rope to a low pulley. After selecting an appropriate weight, grasp the rope with both hands and face away from the cable.","Position your hands behind your head with your elbows point straight up. Your elbows should start out flexed, and you can stagger your stance and lean gently away from the machine to create greater stability. This will be your starting position.","To perform the movement, extend through the elbow while keeping the upper arm in position, raising your hands above your head.","Squeeze your triceps at the top of the movement, and slowly lower the weight back to the start position."]', NULL, '["Triceps_Overhead_Extension_with_Rope/0.jpg","Triceps_Overhead_Extension_with_Rope/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Triceps_Pushdown', 'Triceps Pushdown', 'upper arms', 'triceps', '[]', 'cable', 'strength', 'beginner', '["Attach a straight or angled bar to a high pulley and grab with an overhand grip (palms facing down) at shoulder width.","Standing upright with the torso straight and a very small inclination forward, bring the upper arms close to your body and perpendicular to the floor. The forearms should be pointing up towards the pulley as they hold the bar. This is your starting position.","Using the triceps, bring the bar down until it touches the front of your thighs and the arms are fully extended perpendicular to the floor. The upper arms should always remain stationary next to your torso and only the forearms should move. Exhale as you perform this movement.","After a second hold at the contracted position, bring the bar slowly up to the starting point. Breathe in as you perform this step.","Repeat for the recommended amount of repetitions."]', NULL, '["Triceps_Pushdown/0.jpg","Triceps_Pushdown/1.jpg"]', 5, 'sets', 1, 'fedb', 1),
('fe-Triceps_Pushdown_-_Rope_Attachment', 'Triceps Pushdown - Rope Attachment', 'upper arms', 'triceps', '[]', 'cable', 'strength', 'beginner', '["Attach a rope attachment to a high pulley and grab with a neutral grip (palms facing each other).","Standing upright with the torso straight and a very small inclination forward, bring the upper arms close to your body and perpendicular to the floor. The forearms should be pointing up towards the pulley as they hold the rope with the palms facing each other. This is your starting position.","Using the triceps, bring the rope down as you bring each side of the rope to the side of your thighs. At the end of the movement the arms are fully extended and perpendicular to the floor. The upper arms should always remain stationary next to your torso and only the forearms should move. Exhale as you perform this movement.","After holding for a second, at the contracted position, bring the rope slowly up to the starting point. Breathe in as you perform this step.","Repeat for the recommended amount of repetitions."]', NULL, '["Triceps_Pushdown_-_Rope_Attachment/0.jpg","Triceps_Pushdown_-_Rope_Attachment/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Triceps_Pushdown_-_V-Bar_Attachment', 'Triceps Pushdown - V-Bar Attachment', 'upper arms', 'triceps', '[]', 'cable', 'strength', 'beginner', '["Attach a V-Bar to a high pulley and grab with an overhand grip (palms facing down) at shoulder width.","Standing upright with the torso straight and a very small inclination forward, bring the upper arms close to your body and perpendicular to the floor. The forearms should be pointing up towards the pulley as they hold the bar. The thumbs should be higher than the small finger. This is your starting position.","Using the triceps, bring the bar down until it touches the front of your thighs and the arms are fully extended perpendicular to the floor. The upper arms should always remain stationary next to your torso and only the forearms should move. Exhale as you perform this movement.","After a second hold at the contracted position, bring the V-Bar slowly up to the starting point. Breathe in as you perform this step.","Repeat for the recommended amount of repetitions."]', NULL, '["Triceps_Pushdown_-_V-Bar_Attachment/0.jpg","Triceps_Pushdown_-_V-Bar_Attachment/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Triceps_Stretch', 'Triceps Stretch', 'upper arms', 'triceps', '["lats"]', 'body only', 'stretching', 'beginner', '["Reach your hand behind your head, grasp your elbow and gently pull. Hold for 10 to 20 seconds, then switch sides."]', NULL, '["Triceps_Stretch/0.jpg","Triceps_Stretch/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Two-Arm_Dumbbell_Preacher_Curl', 'Two-Arm Dumbbell Preacher Curl', 'upper arms', 'biceps', '[]', 'dumbbell', 'strength', 'beginner', '["Grab a dumbbell with each arm and place the upper arms on top of the preacher bench or the incline bench. The dumbbell should be held at shoulder length. This will be your starting position.","As you breathe in, slowly lower the dumbbells until your upper arm is extended and the biceps is fully stretched.","As you exhale, use the biceps to curl the weights up until your biceps is fully contracted and the dumbbells are at shoulder height.","Squeeze the biceps hard for a second at the contracted position and repeat for the recommended amount of repetitions."]', NULL, '["Two-Arm_Dumbbell_Preacher_Curl/0.jpg","Two-Arm_Dumbbell_Preacher_Curl/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Two-Arm_Kettlebell_Jerk', 'Two-Arm Kettlebell Jerk', 'shoulders', 'shoulders', '["calves","quadriceps","triceps"]', 'kettlebells', 'strength', 'intermediate', '["Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you swing the kettlebells towards your shoulders. Rotate your wrists as you do so, so that the palms face forward. Squat down a few inches and reverse the motion rapidly driving both kettlebells overhead. Immediately after the initial push, squat down again and get under the kettlebells. Once the kettlebells are locked out, stand upright to complete the exercise."]', NULL, '["Two-Arm_Kettlebell_Jerk/0.jpg","Two-Arm_Kettlebell_Jerk/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Upper_Back-Leg_Grab', 'Upper Back-Leg Grab', 'upper legs', 'hamstrings', '["lower back","middle back"]', 'body only', 'stretching', 'beginner', '["While seated, bend forward to hug your thighs from underneath with both arms.","Keep your knees together and your legs extended out as you bring your chest down to your knees. You can also stretch your middle back by pulling your back away from your knees as your hugging them."]', NULL, '["Upper_Back-Leg_Grab/0.jpg","Upper_Back-Leg_Grab/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Upper_Back_Stretch', 'Upper Back Stretch', 'back', 'middle back', '["middle back"]', 'body only', 'stretching', 'beginner', '["Clasp fingers together with your thumbs pointing down, round your shoulders as you reach your hands forward."]', NULL, '["Upper_Back_Stretch/0.jpg","Upper_Back_Stretch/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Upright_Row_-_With_Bands', 'Upright Row - With Bands', 'back', 'traps', '["shoulders"]', 'bands', 'strength', 'beginner', '["To begin, stand on an exercise band so that tension begins at arm''s length. Grasp the handles using a pronated (palms facing your thighs) grip that is slightly less than shoulder width. The handles should be resting on top of your thighs. Your arms should be extended with a slight bend at the elbows and your back should be straight. This will be your starting position.","Use your side shoulders to lift the handles as you exhale. The handles should be close to the body as you move them up. Continue to lift the handles until they nearly touches your chin. Tip: Your elbows should drive the motion. As you lift the handles, your elbows should always be higher than your forearms. Also, keep your torso stationary and pause for a second at the top of the movement.","Lower the handles back down slowly to the starting position. Inhale as you perform this portion of the movement.","Repeat for the recommended amount of repetitions."]', NULL, '["Upright_Row_-_With_Bands/0.jpg","Upright_Row_-_With_Bands/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Upward_Stretch', 'Upward Stretch', 'shoulders', 'shoulders', '["chest","lats"]', 'body only', 'stretching', 'beginner', '["Extend both hands straight above your head, palms touching.","Slowly push your hands up and back, keeping your back straight."]', NULL, '["Upward_Stretch/0.jpg","Upward_Stretch/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-V-Bar_Pulldown', 'V-Bar Pulldown', 'back', 'lats', '["biceps","middle back","shoulders"]', 'cable', 'strength', 'intermediate', '["Sit down on a pull-down machine with a V-Bar attached to the top pulley.","Adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.","Grab the V-bar with the palms facing each other (a neutral grip). Stick your chest out and lean yourself back slightly (around 30-degrees) in order to better engage the lats. This will be your starting position.","Using your lats, pull the bar down as you squeeze your shoulder blades. Continue until your chest nearly touches the V-bar. Exhale as you execute this motion. Tip: Keep the torso stationary throughout the movement.","After a second hold on the contracted position, slowly bring the bar back to the starting position as you breathe in.","Repeat for the prescribed number of repetitions."]', NULL, '["V-Bar_Pulldown/0.jpg","V-Bar_Pulldown/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-V-Bar_Pullup', 'V-Bar Pullup', 'back', 'lats', '["biceps","middle back","shoulders"]', 'body only', 'strength', 'beginner', '["Start by placing the middle of the V-bar in the middle of the pull-up bar (assuming that the pull-up station you are using does not have neutral grip handles). The V-Bar handles will be facing down so that you can hang from the pull-up bar through the use of the handles.","Once you securely place the V-bar, take a hold of the bar from each side and hang from it. Stick your chest out and lean yourself back slightly in order to better engage the lats. This will be your starting position.","Using your lats, pull your torso up while leaning your head back slightly so that you do not hit yourself with the chin-up bar. Continue until your chest nearly touches the V-bar. Exhale as you execute this motion.","After a second hold on the contracted position, slowly lower your body back to the starting position as you breathe in.","Repeat for the prescribed number of repetitions."]', NULL, '["V-Bar_Pullup/0.jpg","V-Bar_Pullup/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Vertical_Swing', 'Vertical Swing', 'upper legs', 'hamstrings', '["glutes","quadriceps","shoulders"]', 'dumbbell', 'plyometrics', 'beginner', '["Allow the dumbbell to hang at arms length between your legs, holding it with both hands. Keep your back straight and your head up.","Swing the dumbbell between your legs, flexing at the hips and bending the knees slightly.","Powerfully reverse the motion by extending at the hips, knees, and ankles to propel yourself upward, swinging the dumbell over your head.","As you land, absorb the impact through your legs and draw the dumbbell to your torso before the next repetition."]', NULL, '["Vertical_Swing/0.jpg","Vertical_Swing/1.jpg"]', 8, 'sets', 0, 'fedb', 1),
('fe-Walking_Treadmill', 'Walking, Treadmill', 'cardio', 'quadriceps', '["calves","glutes","hamstrings"]', 'machine', 'cardio', 'beginner', '["To begin, step onto the treadmill and select the desired option from the menu. Most treadmills have a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. Elevation can be adjusted to change the intensity of the workout.","Treadmills offer convenience, cardiovascular benefits, and usually have less impact than walking outside. When walking, you should move at a moderate to fast pace, not a leisurely one. Being an activity of lower intensity, walking doesn''t burn as many calories as some other activities, but still provides great benefit. A 150 lb person will burn about 175 calories walking 4 miles per hour for 30 minutes, compared to 450 calories running twice as fast. Maintain proper posture as you walk, and only hold onto the handles when necessary, such as when dismounting or checking your heart rate."]', NULL, '["Walking_Treadmill/0.jpg","Walking_Treadmill/1.jpg"]', 3.5, 'time', 0, 'fedb', 1),
('fe-Weighted_Ball_Hyperextension', 'Weighted Ball Hyperextension', 'back', 'lower back', '["glutes","hamstrings","middle back"]', 'exercise ball', 'strength', 'intermediate', '["To begin, lie down on an exercise ball with your torso pressing against the ball and parallel to the floor. The ball of your feet should be pressed against the floor to help keep you balanced. Place a weighted plate under your chin or behind your neck. This is the starting position.","Slowly raise your torso up by bending at the waist and lower back. Remember to exhale during this movement.","Hold the contraction on your lower back for a second and lower your torso back down to the starting position while inhaling.","Repeat for the recommended amount of repetitions prescribed in your program."]', NULL, '["Weighted_Ball_Hyperextension/0.jpg","Weighted_Ball_Hyperextension/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Weighted_Ball_Side_Bend', 'Weighted Ball Side Bend', 'waist', 'abdominals', '[]', 'exercise ball', 'strength', 'intermediate', '["To begin, lie down on an exercise ball with your left side of the torso (waist, hips and shoulder) pressed against the ball.","Your feet should be on the floor while your legs are crossed and hanging from the ball. Hold a weighted plate with your right hand directly to the right side of your head. Tip: Make sure the smooth side of the plate is resting against your head.","Place your left arm across your torso so that your palm is on your obliques. There should be a right angle between your left forearm and upper arm. This is the starting position.","Raise the side of your torso up by laterally flexing at the waist while exhaling.","Hold the contraction for a second and slowly lower yourself back down to the starting position while inhaling.","Repeat for the recommended amount of repetitions.","Switch sides and repeat the exercise."]', NULL, '["Weighted_Ball_Side_Bend/0.jpg","Weighted_Ball_Side_Bend/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Weighted_Bench_Dip', 'Weighted Bench Dip', 'upper arms', 'triceps', '["chest","shoulders"]', 'other', 'strength', 'intermediate', '["For this exercise you will need to place a bench behind your back and another one in front of you. With the benches perpendicular to your body, hold on to one bench on its edge with the hands close to your body, separated at shoulder width. Your arms should be fully extended.","The legs will be extended forward on top of the other bench. Your legs should be parallel to the floor while your torso is to be perpendicular to the floor. Have your partner place the dumbbell on your lap. Note: This exercise is best performed with a partner as placing the weight on your lap can be challenging and cause injury without assistance. This will be your starting position.","Slowly lower your body as you inhale by bending at the elbows until you lower yourself far enough to where there is an angle slightly smaller than 90 degrees between the upper arm and the forearm. Tip: Keep the elbows as close as possible throughout the movement. Forearms should always be pointing down.","Using your triceps to bring your torso up again, lift yourself back to the starting position while exhaling.","Repeat for the recommended amount of repetitions."]', NULL, '["Weighted_Bench_Dip/0.jpg","Weighted_Bench_Dip/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Weighted_Crunches', 'Weighted Crunches', 'waist', 'abdominals', '[]', 'medicine ball', 'strength', 'beginner', '["Lie flat on your back with your feet flat on the ground or resting on a bench with your knees bent at a 90 degree angle.","Hold a weight to your chest, or you may hold it extended above your torso. This will be your starting position.","Now, exhale and slowly begin to roll your shoulders off the floor. Your shoulders should come up off the floor about 4 inches while your lower back remains on the floor.","At the top of the movement, flex your abdominals and hold for a brief pause.","Then inhale and slowly lower yourself back down to the starting position."]', NULL, '["Weighted_Crunches/0.jpg","Weighted_Crunches/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Weighted_Jump_Squat', 'Weighted Jump Squat', 'upper legs', 'quadriceps', '["calves","glutes","hamstrings","lower back"]', 'barbell', 'strength', 'intermediate', '["Position a lightly loaded barbell across the back of your shoulders. You could also use a weighted vest, sandbag, or other type of resistance for this exercise.","The weight should be light enough that it doesn''t slow you down significantly. Your feet should be just outside of shoulder width with your head and chest up. This will be your starting position.","Using a countermovement, squat partially down and immediately reverse your direction to explode off of the ground, extending through your hips, knees, and ankles. Maintain good posture throughout the jump.","As you return to the ground, absorb the impact through your legs."]', NULL, '["Weighted_Jump_Squat/0.jpg","Weighted_Jump_Squat/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Weighted_Pull_Ups', 'Weighted Pull Ups', 'back', 'lats', '["biceps","middle back"]', 'other', 'strength', 'intermediate', '["Attach a weight to a dip belt and secure it around your waist. Grab the pull-up bar with the palms of your hands facing forward. For a medium grip, your hands should be spaced at shoulder width. Both arms should be extended in front of you holding the bar at the chosen grip.","You''ll want to bring your torso back about 30 degrees while creating a curvature in your lower back and sticking your chest out. This will be your starting position.","Now, exhale and pull your torso up until your head is above your hands. Concentrate on squeezing yourshoulder blades back and down as you reach the top contracted position.","After a brief moment at the top contracted position, inhale and slowly lower your torso back to the starting position with your arms extended and your lats fully stretched."]', NULL, '["Weighted_Pull_Ups/0.jpg","Weighted_Pull_Ups/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Weighted_Sissy_Squat', 'Weighted Sissy Squat', 'upper legs', 'quadriceps', '["calves","glutes","hamstrings"]', 'barbell', 'strength', 'expert', '["Standing upright, with feet at shoulder width and toes raised, use one hand to hold onto the beams of a squat rack and the opposite arm to hold a plate on top of your chest. This is your starting position.","As you use one arm to hold yourself, bend at the knees and slowly lower your torso toward the ground by bringing your pelvis and knees forward. Inhale as you go down and stop when your upper and lower legs almost create a 90-degree angle. Hold the stretch position for a second.","After your one second hold, use your thigh muscles to bring your torso back up to the starting position. Exhale as you move up.","Repeat for the recommended amount of times."]', NULL, '["Weighted_Sissy_Squat/0.jpg","Weighted_Sissy_Squat/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Weighted_Sit-Ups_-_With_Bands', 'Weighted Sit-Ups - With Bands', 'waist', 'abdominals', '[]', 'other', 'strength', 'intermediate', '["Start out by strapping the bands around the base of the decline bench. Place the handles towards the inside of the decline bench so that when lying down, you can reach for both of them.","Position your legs through the decline machine until they are secured. Now reach for the exercise bands with both hands. Use a pronated (palms forward) grip to grasp the handles. Position them near your collar bone and rotate your wrist to a neutral grip (palms facing the torso). Note: Your arms should remain stationary throughout the exercise. This is the starting position.","Move your torso upward until your upper body is perpendicular to the floor while exhaling. Hold the contraction for a second and lower your upper body back down to the starting position while inhaling.","Repeat for the recommended amount of repetitions."]', NULL, '["Weighted_Sit-Ups_-_With_Bands/0.jpg","Weighted_Sit-Ups_-_With_Bands/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Weighted_Squat', 'Weighted Squat', 'upper legs', 'quadriceps', '["calves","glutes","hamstrings"]', 'other', 'strength', 'intermediate', '["Start by positioning two flat benches shoulder width apart from each other. Stand on top of them and wrap the weighted belt around your waist with the amount of weight you feel comfortable with. Make sure your toes are facing out.","Once you are standing straight up with the weight hanging in between your legs, position your arms so that they are fully extended to the side of your body. This is the starting position.","Begin by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that are perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.","Begin to move the body back up by pushing the floor of the flat bench with the ball of your foot mainly as you straighten the legs again and go back to the starting position. Exhale as you perform this portion of the exercise.","Repeat for the recommended amount of repetitions."]', NULL, '["Weighted_Squat/0.jpg","Weighted_Squat/1.jpg"]', 5, 'sets', 0, 'fedb', 1)
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('fe-Wide-Grip_Decline_Barbell_Bench_Press', 'Wide-Grip Decline Barbell Bench Press', 'chest', 'chest', '["shoulders","triceps"]', 'barbell', 'strength', 'intermediate', '["Lie back on a decline bench with the feet securely locked at the front of the bench. Using a wide, pronated (palms forward) grip that is around 3 inches away from shoulder width (for each hand), lift the bar from the rack and hold it straight over you with your arms locked. The bar will be perpendicular to the torso and the floor. This will be your starting position.","As you breathe in, come down slowly until you feel the bar on your lower chest.","After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.","Repeat the movement for the prescribed amount of repetitions."]', NULL, '["Wide-Grip_Decline_Barbell_Bench_Press/0.jpg","Wide-Grip_Decline_Barbell_Bench_Press/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Wide-Grip_Lat_Pulldown', 'Wide-Grip Lat Pulldown', 'back', 'lats', '["biceps","middle back","shoulders"]', 'cable', 'strength', 'beginner', '["Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.","Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.","As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.","As you breathe out, bring the bar down until it touches your upper chest by drawing the shoulders and the upper arms down and back. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary and only the arms should move. The forearms should do no other work except for holding the bar; therefore do not try to pull down the bar using the forearms.","After a second at the contracted position squeezing your shoulder blades together, slowly raise the bar back to the starting position when your arms are fully extended and the lats are fully stretched. Inhale during this portion of the movement.","Repeat this motion for the prescribed amount of repetitions."]', NULL, '["Wide-Grip_Lat_Pulldown/0.jpg","Wide-Grip_Lat_Pulldown/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Wide-Grip_Pulldown_Behind_The_Neck', 'Wide-Grip Pulldown Behind The Neck', 'back', 'lats', '["biceps","middle back","shoulders"]', 'cable', 'strength', 'intermediate', '["Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.","Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than your shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.","As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso and head forward. Think of an imaginary line from the center of the bar down to the back of your neck. This is your starting position.","As you breathe out, bring the bar down until it touches the back of your neck by drawing the shoulders and the upper arms down and back. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary and only the arms should move. The forearms should do no other work except for holding the bar; therefore do not try to pull down the bar using the forearms.","After a second on the contracted position squeezing your shoulder blades together, slowly raise the bar back to the starting position when your arms are fully extended and the lats are fully stretched. Inhale during this portion of the movement.","Repeat this motion for the prescribed amount of repetitions."]', NULL, '["Wide-Grip_Pulldown_Behind_The_Neck/0.jpg","Wide-Grip_Pulldown_Behind_The_Neck/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Wide_Stance_Barbell_Squat', 'Wide Stance Barbell Squat', 'upper legs', 'quadriceps', '["calves","glutes","hamstrings","lower back"]', 'barbell', 'strength', 'intermediate', '["This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.","Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.","Step away from the rack and position your legs using a wider-than-shoulder-width stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance, and also maintain a straight back. This will be your starting position.","Begin to slowly lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.","Begin to raise the bar as you exhale by pushing the floor with the heel of your foot as you straighten the legs again and go back to the starting position.","Repeat for the recommended amount of repetitions."]', NULL, '["Wide_Stance_Barbell_Squat/0.jpg","Wide_Stance_Barbell_Squat/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Wide_Stance_Stiff_Legs', 'Wide Stance Stiff Legs', 'upper legs', 'hamstrings', '["adductors","glutes","lower back"]', 'barbell', 'olympic weightlifting', 'intermediate', '["Begin with a barbell loaded on the floor. Adopt a wide stance, and then bend at the hips to grab the bar. Your hips should be as far back as possible, and your legs nearly straight. Keep your back straight, and your head and chest up. This will be your starting position.","Begin the movement be engaging the hips, driving them forward as you allow the arms to hang straight. Continue until you are standing straight up, and then slowly return the weight to the starting position. For successive reps, the weight need not touch the floor."]', NULL, '["Wide_Stance_Stiff_Legs/0.jpg","Wide_Stance_Stiff_Legs/1.jpg"]', 6, 'sets', 0, 'fedb', 1),
('fe-Windmills', 'Windmills', 'upper legs', 'abductors', '["glutes","hamstrings","lower back"]', 'body only', 'stretching', 'intermediate', '["Lie on your back with your arms extended out to the sides and your legs straight. This will be your starting position.","Lift one leg and quickly cross it over your body, attempting to touch the ground near the opposite hand.","Return to the starting position, and repeat with the opposite leg. Continue to alternate for 10-20 repetitions."]', NULL, '["Windmills/0.jpg","Windmills/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Worlds_Greatest_Stretch', 'World''s Greatest Stretch', 'upper legs', 'hamstrings', '["calves","glutes","quadriceps"]', 'body only', 'stretching', 'intermediate', '["This is a three-part stretch. Begin by lunging forward, with your front foot flat on the ground and on the toes of your back foot. With your knees bent, squat down until your knee is almost touching the ground. Keep your torso erect, and hold this position for 10-20 seconds.","Now, place the arm on the same side as your front leg on the ground, with the elbow next to the foot. Your other hand should be placed on the ground, parallel to your lead leg, to help support you during this portion of the stretch.","After 10-20 seconds, place your hands on either side of your front foot. Raise the toes of the front foot off of the ground, and straighten your leg. You may need to reposition your rear leg to do so. Hold for 10-20 seconds, and then repeat the entire sequence for the other side."]', NULL, '["Worlds_Greatest_Stretch/0.jpg","Worlds_Greatest_Stretch/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Wrist_Roller', 'Wrist Roller', 'lower arms', 'forearms', '["shoulders"]', 'other', 'strength', 'beginner', '["To begin, stand straight up grabbing a wrist roller using a pronated grip (palms facing down). Your feet should be shoulder width apart.","Slowly lift both arms until they are fully extended and parallel to the floor in front of you. Note: Make sure the rope is not wrapped around the roller. Your entire body should be stationary except for the forearms. This is the starting position.","Rotate one wrist at a time in an upward motion to bring the weight up to the bar by rolling the rope around the roller.","Once the weight has reached the bar, slowly begin to lower the weight back down by rotating the wrist in a downward motion until the weight reaches the starting position.","Repeat for the prescribed amount of repetitions in your program."]', NULL, '["Wrist_Roller/0.jpg","Wrist_Roller/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Wrist_Rotations_with_Straight_Bar', 'Wrist Rotations with Straight Bar', 'lower arms', 'forearms', '[]', 'barbell', 'strength', 'beginner', '["Hold a barbell with both hands and your palms facing down; hands spaced about shoulder width. This will be your starting position.","Alternating between each of your hands, perform the movement by extending the wrist as though you were rolling up a newspaper. Continue alternating back and forth until failure.","Reverse the motion by flexing the wrist, rolling the opposite direction. Continue the alternating motion until failure."]', NULL, '["Wrist_Rotations_with_Straight_Bar/0.jpg","Wrist_Rotations_with_Straight_Bar/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Yoke_Walk', 'Yoke Walk', 'upper legs', 'quadriceps', '["abdominals","abductors","adductors","calves","glutes","hamstrings","lower back"]', 'other', 'strongman', 'intermediate', '["The yoke is usually done with a yoke apparatus, but is sometimes seen with refrigerators or other heavy objects.","Begin by racking the apparatus across the back of the shoulders. With your head looking forward and back arched, lift the yoke by driving through the heels.","Begin walking as quickly as possible using short, quick steps. You may hold the side posts of the yoke to help steady it and hold it in position. Continue for the given distance as fast as possible, usually 75-100 feet."]', NULL, '["Yoke_Walk/0.jpg","Yoke_Walk/1.jpg"]', 3.5, 'sets', 0, 'fedb', 1),
('fe-Zercher_Squats', 'Zercher Squats', 'upper legs', 'quadriceps', '["calves","glutes","hamstrings"]', 'barbell', 'strength', 'expert', '["This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. The correct height should be anywhere above the waist but below the chest. Once the correct height is chosen and the bar is loaded, lock your hands together and place the bar on top of your arms in between the forearm and upper arm.","Lift the bar up so that it is resting on top of your forearms. If you are holding the bar properly, it should look as if you have your arms crossed but with a bar running across them.","Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section).","Begin to lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.","Begin to raise the bar as you exhale by pushing the floor with the ball of your foot mainly as you straighten the legs again and go back to the starting position.","Repeat for the recommended amount of repetitions."]', NULL, '["Zercher_Squats/0.jpg","Zercher_Squats/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Zottman_Curl', 'Zottman Curl', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', 'intermediate', '["Stand up with your torso upright and a dumbbell in each hand being held at arms length. The elbows should be close to the torso.","Make sure the palms of the hands are facing each other. This will be your starting position.","While holding the upper arm stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Your wrist should rotate so that you have a supinated (palms up) grip. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a second as you squeeze the biceps.","Now during the contracted position, rotate your wrist until you now have a pronated (palms facing down) grip with the thumb at a higher position than the pinky.","Slowly begin to bring the dumbbells back down using the pronated grip.","As the dumbbells close your thighs, start rotating the wrist so that you go back to a neutral (palms facing your body) grip.","Repeat for the recommended amount of repetitions."]', NULL, '["Zottman_Curl/0.jpg","Zottman_Curl/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Zottman_Preacher_Curl', 'Zottman Preacher Curl', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', 'intermediate', '["Grab a dumbbell in each hand and place your upper arms on top of the preacher bench or the incline bench. The dumbbells should be held at shoulder height and the elbows should be flexed. Hold the dumbbells with the palms of your hands facing down. This will be your starting position.","As you breathe in, slowly lower the dumbbells keeping the palms down until your upper arm is extended and your biceps are fully stretched.","Now rotate your wrists once you are at the bottom of the movement so that the palms of the hands are facing up.","As you exhale, use your biceps to curl the weights up until they are fully contracted and the dumbbells are at shoulder height. Again, remember that to ensure full contraction you need to bring that small finger higher than the thumb.","Squeeze the biceps hard for a second at the contracted position and rotate your wrists so that the palms are facing down again.","Repeat for the recommended amount of repetitions."]', NULL, '["Zottman_Preacher_Curl/0.jpg","Zottman_Preacher_Curl/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
